  {"n":19,"r":"Règle 16.1a-b","s":"La balle de Nora repose sur un chemin artificiel dans la zone générale.","e":"Un chemin artificiel est généralement une obstruction inamovible; si elle gêne le lie, le stance ou le swing, un dégagement complet gratuit est possible, sauf restriction ou objet intégrant le parcours.","a":"Je trouve le point le plus proche de dégagement complet, puis droppe dans la zone d’une longueur de club sans me rapprocher du trou.","m":"Dropper du côté qui paraît le plus favorable sans déterminer le point de référence.","c":"Tracez le point et la zone avec une ficelle; faites vérifier l’absence d’interférence.","v":"Balle sur un chemin artificiel, joueur mesurant un point de dégagement.","q":[{"v":0,"p":"Une balle repose sur un chemin artificiel qui gêne le stance. Quelle option habituelle ?","i":"Balle sur un chemin artificiel, joueur mesurant un point de dégagement. Une balle repose sur un chemin artificiel qui gêne le stance. Quelle option habituelle ?","x":"Un chemin artificiel est généralement une obstruction inamovible; si elle gêne le lie, le stance ou le swing, un dégagement complet gratuit est possible, sauf restriction ou objet intégrant le parcours.","o":[["Dégagement complet gratuit selon la Règle 16","Oui. Le chemin inamovible est une condition anormale."],["Dropper n’importe où sur le fairway","Non. La zone est déterminée à partir du point le plus proche."],["Ajouter automatiquement deux coups","Non. Le dégagement autorisé est gratuit."]]},{"v":1,"p":"Le sentier artificiel gêne le swing de Tom dans la zone générale. Que peut-il choisir ?","i":"Balle sur un chemin artificiel, joueur mesurant un point de dégagement. Le sentier artificiel gêne le swing de Tom dans la zone générale. Que peut-il choisir ?","x":"Un chemin artificiel est généralement une obstruction inamovible; si elle gêne le lie, le stance ou le swing, un dégagement complet gratuit est possible, sauf restriction ou objet intégrant le parcours.","o":[["Dégagement complet gratuit selon la Règle 16","Oui. Le chemin inamovible est une condition anormale."],["Dropper n’importe où sur le fairway","Non. La zone est déterminée à partir du point le plus proche."],["Ajouter automatiquement deux coups","Non. Le dégagement autorisé est gratuit."]]},{"v":2,"p":"La balle de Sara repose sur une allée pavée non déclarée partie intégrante. Quelle procédure possible ?","i":"Balle sur un chemin artificiel, joueur mesurant un point de dégagement. La balle de Sara repose sur une allée pavée non déclarée partie intégrante. Quelle procédure possible ?","x":"Un chemin artificiel est généralement une obstruction inamovible; si elle gêne le lie, le stance ou le swing, un dégagement complet gratuit est possible, sauf restriction ou objet intégrant le parcours.","o":[["Dégagement complet gratuit selon la Règle 16","Oui. Le chemin inamovible est une condition anormale."],["Dropper n’importe où sur le fairway","Non. La zone est déterminée à partir du point le plus proche."],["Ajouter automatiquement deux coups","Non. Le dégagement autorisé est gratuit."]]}]},
  {"n":20,"r":"Définition « Eau temporaire » ; Règle 16.1","s":"Après avoir pris son stance, Hugo voit de l’eau temporaire affleurer autour de sa chaussure près de sa balle.","e":"L’eau temporaire est une accumulation visible qui n’est ni une zone à pénalité ni une partie normale du parcours; si elle gêne lie, stance ou swing, un dégagement gratuit est normalement possible hors zone à pénalité.","a":"Je vérifie l’eau visible avant ou après le stance, puis cherche un dégagement complet adapté à la zone.","m":"Prendre toute herbe humide pour de l’eau temporaire.","c":"Versez un peu d’eau sur une zone d’exercice autorisée et comparez sol humide et accumulation visible.","v":"Pied d’un junior dans une flaque temporaire proche de sa balle.","q":[{"v":0,"p":"De l’eau affleure sous tes pieds après avoir pris ton stance. Que vérifies-tu ?","i":"Pied d’un junior dans une flaque temporaire proche de sa balle. De l’eau affleure sous tes pieds après avoir pris ton stance. Que vérifies-tu ?","x":"L’eau temporaire est une accumulation visible qui n’est ni une zone à pénalité ni une partie normale du parcours; si elle gêne lie, stance ou swing, un dégagement gratuit est normalement possible hors zone à pénalité.","o":[["Vérifier l’interférence par une accumulation visible","Oui. C’est le critère essentiel de l’eau temporaire."],["Traiter toute humidité comme un dégagement","Non. Une simple humidité ne suffit pas."],["Déclarer automatiquement la balle perdue","Non. La balle est présente et l’interférence se vérifie."]]},{"v":1,"p":"Une flaque non marquée gêne la position de jeu de Léa dans la zone générale. Quelle option ?","i":"Pied d’un junior dans une flaque temporaire proche de sa balle. Une flaque non marquée gêne la position de jeu de Léa dans la zone générale. Quelle option ?","x":"L’eau temporaire est une accumulation visible qui n’est ni une zone à pénalité ni une partie normale du parcours; si elle gêne lie, stance ou swing, un dégagement gratuit est normalement possible hors zone à pénalité.","o":[["Un dégagement gratuit complet peut être possible","Oui. L’eau temporaire interfère avec son stance dans la zone générale."],["Aucune option parce que la flaque n’est pas marquée","Non. L’eau temporaire n’a pas besoin d’une ligne du Comité."],["Un drop libre au meilleur endroit","Non. La procédure détermine le point et la zone."]]},{"v":2,"p":"Le sol est seulement humide, sans eau visible même après le stance. Peut-on invoquer l’eau temporaire ?","i":"Pied d’un junior dans une flaque temporaire proche de sa balle. Le sol est seulement humide, sans eau visible même après le stance. Peut-on invoquer l’eau temporaire ?","x":"L’eau temporaire est une accumulation visible qui n’est ni une zone à pénalité ni une partie normale du parcours; si elle gêne lie, stance ou swing, un dégagement gratuit est normalement possible hors zone à pénalité.","o":[["Non, une simple humidité ne suffit pas","Oui. Il faut une accumulation visible avant ou après le stance."],["Oui, tout sol humide est de l’eau temporaire","Non. L’humidité seule ne répond pas à la définition."],["Oui, si la balle est loin du green","Non. La distance au green n’est pas le critère."]]}]},
  {"n":21,"r":"Règle 16.1 ; définition « Terrain en réparation »","s":"La balle d’Ana s’arrête dans une parcelle entourée d’une ligne blanche et annoncée terrain en réparation.","e":"Le terrain en réparation défini par le Comité est une condition anormale. Hors zone à pénalité, une interférence peut permettre un dégagement complet gratuit; une zone de jeu interdit impose de ne pas jouer la balle telle qu’elle repose.","a":"Je vérifie la signalisation du Comité et prends le dégagement requis ou autorisé selon le marquage.","m":"Ignorer une zone de jeu interdit ou supposer que toute terre nue est en réparation.","c":"Montrez plusieurs zones, dont une non marquée et une zone de jeu interdit.","v":"Balle dans une zone de terrain en réparation marquée par le Comité.","q":[{"v":0,"p":"La balle est dans un terrain en réparation marqué. Que faut-il vérifier avant de jouer ?","i":"Balle dans une zone de terrain en réparation marquée par le Comité. La balle est dans un terrain en réparation marqué. Que faut-il vérifier avant de jouer ?","x":"Le terrain en réparation défini par le Comité est une condition anormale. Hors zone à pénalité, une interférence peut permettre un dégagement complet gratuit; une zone de jeu interdit impose de ne pas jouer la balle telle qu’elle repose.","o":[["Appliquer la signalisation et la règle de dégagement","Oui. Le marquage du Comité et la zone déterminent la procédure."],["Toujours jouer sans regarder le marquage","Non. Une zone de jeu interdit peut imposer un dégagement."],["Déplacer librement la balle sur le fairway","Non. Le dégagement suit une zone définie."]]},{"v":1,"p":"Une zone marquée comme terrain en réparation gêne le stance de Max hors zone à pénalité. Quelle possibilité ?","i":"Balle dans une zone de terrain en réparation marquée par le Comité. Une zone marquée comme terrain en réparation gêne le stance de Max hors zone à pénalité. Quelle possibilité ?","x":"Le terrain en réparation défini par le Comité est une condition anormale. Hors zone à pénalité, une interférence peut permettre un dégagement complet gratuit; une zone de jeu interdit impose de ne pas jouer la balle telle qu’elle repose.","o":[["Appliquer la signalisation et la règle de dégagement","Oui. Le marquage du Comité et la zone déterminent la procédure."],["Toujours jouer sans regarder le marquage","Non. Une zone de jeu interdit peut imposer un dégagement."],["Déplacer librement la balle sur le fairway","Non. Le dégagement suit une zone définie."]]},{"v":2,"p":"Un panneau signale une zone de jeu interdit dans le terrain en réparation. Peut-on jouer la balle sur place ?","i":"Balle dans une zone de terrain en réparation marquée par le Comité. Un panneau signale une zone de jeu interdit dans le terrain en réparation. Peut-on jouer la balle sur place ?","x":"Le terrain en réparation défini par le Comité est une condition anormale. Hors zone à pénalité, une interférence peut permettre un dégagement complet gratuit; une zone de jeu interdit impose de ne pas jouer la balle telle qu’elle repose.","o":[["Non, il faut prendre le dégagement requis","Oui. Une zone de jeu interdit ne peut pas être jouée telle quelle."],["Oui, si la balle est visible","Non. La visibilité ne supprime pas l’interdiction."],["Oui, avec un coup de pénalité sur place","Non. Le jeu depuis cette zone reste interdit."]]}]},
  {"n":22,"r":"Règle 16.1 ; définition « Trou d’animal »","s":"La balle de Léo est près d’un terrier et le trou d’un animal gêne son stance.","e":"Un trou d’animal est une condition anormale; s’il interfère avec le lie, le stance ou le swing, un dégagement gratuit peut être disponible hors zone à pénalité. Une simple empreinte d’animal n’est pas nécessairement un trou d’animal.","a":"Je constate le trou et l’interférence, puis utilise le point le plus proche de dégagement complet.","m":"Assimiler toute trace de patte à un trou d’animal.","c":"Comparez un vrai terrier et de simples traces laissées sur le sol.","v":"Terrier et balle proches, pied du junior dans l’entrée du trou.","q":[{"v":0,"p":"Un terrier gêne ton stance dans la zone générale. Quelle possibilité ?","i":"Terrier et balle proches, pied du junior dans l’entrée du trou. Un terrier gêne ton stance dans la zone générale. Quelle possibilité ?","x":"Un trou d’animal est une condition anormale; s’il interfère avec le lie, le stance ou le swing, un dégagement gratuit peut être disponible hors zone à pénalité. Une simple empreinte d’animal n’est pas nécessairement un trou d’animal.","o":[["Vérifier l’interférence et le dégagement gratuit","Oui. Le trou peut constituer une condition anormale."],["Dropper où la balle sera le mieux placée","Non. La zone de dégagement est définie."],["Déclarer toute empreinte comme un trou","Non. Une simple trace ne suffit pas."]]},{"v":1,"p":"Le trou creusé par un animal interfère avec le swing de Mia. Que vérifie-t-elle ?","i":"Terrier et balle proches, pied du junior dans l’entrée du trou. Le trou creusé par un animal interfère avec le swing de Mia. Que vérifie-t-elle ?","x":"Un trou d’animal est une condition anormale; s’il interfère avec le lie, le stance ou le swing, un dégagement gratuit peut être disponible hors zone à pénalité. Une simple empreinte d’animal n’est pas nécessairement un trou d’animal.","o":[["Vérifier l’interférence et le dégagement gratuit","Oui. Le trou peut constituer une condition anormale."],["Dropper où la balle sera le mieux placée","Non. La zone de dégagement est définie."],["Déclarer toute empreinte comme un trou","Non. Une simple trace ne suffit pas."]]},{"v":2,"p":"Noé voit seulement des empreintes d’animal sans trou. Peut-il les traiter automatiquement comme un trou d’animal ?","i":"Terrier et balle proches, pied du junior dans l’entrée du trou. Noé voit seulement des empreintes d’animal sans trou. Peut-il les traiter automatiquement comme un trou d’animal ?","x":"Un trou d’animal est une condition anormale; s’il interfère avec le lie, le stance ou le swing, un dégagement gratuit peut être disponible hors zone à pénalité. Une simple empreinte d’animal n’est pas nécessairement un trou d’animal.","o":[["Non, les empreintes seules ne suffisent pas","Oui. Il faut vérifier l’existence d’un véritable trou d’animal."],["Oui, toute trace d’animal donne un dégagement","Non. Une empreinte n’est pas nécessairement un trou."],["Oui, s’il préfère le fairway","Non. Le choix de lie ne crée pas une condition anormale."]]}]},
  {"n":23,"r":"Règle 16.3","s":"Dans la zone générale, une balle jouée par Emma s’enfonce dans son propre impact dans le sol.","e":"Une balle enfoncée dans son propre impact dans la zone générale peut généralement bénéficier d’un dégagement gratuit, sauf notamment si elle est enfoncée dans du sable d’une partie de la zone générale non tondue à hauteur du fairway ou moins.","a":"Je confirme qu’une partie de la balle est sous le niveau du sol dans son propre impact et je suis la procédure de la Règle 16.3.","m":"Confondre une balle coincée dans l’herbe avec une balle enfoncée dans son impact.","c":"Faites comparer un impact récent, une balle dans une touffe et une balle dans du sable.","v":"Balle partiellement sous le niveau du sol dans son propre impact sur le fairway.","q":[{"v":0,"p":"Une balle dans la zone générale est enfoncée dans son propre impact. Quelle option générale ?","i":"Balle partiellement sous le niveau du sol dans son propre impact sur le fairway. Une balle dans la zone générale est enfoncée dans son propre impact. Quelle option générale ?","x":"Une balle enfoncée dans son propre impact dans la zone générale peut généralement bénéficier d’un dégagement gratuit, sauf notamment si elle est enfoncée dans du sable d’une partie de la zone générale non tondue à hauteur du fairway ou moins.","o":[["Vérifier les critères puis prendre un dégagement gratuit","Oui. L’impact propre et la zone doivent être confirmés."],["La déplacer librement sans référence","Non. La procédure de dégagement est précise."],["Considérer toute balle difficile comme enfoncée","Non. Un mauvais lie ne suffit pas."]]},{"v":1,"p":"Une balle de Noé est partiellement sous le niveau du sol dans son impact au fairway. Que vérifie-t-il ?","i":"Balle partiellement sous le niveau du sol dans son propre impact sur le fairway. Une balle de Noé est partiellement sous le niveau du sol dans son impact au fairway. Que vérifie-t-il ?","x":"Une balle enfoncée dans son propre impact dans la zone générale peut généralement bénéficier d’un dégagement gratuit, sauf notamment si elle est enfoncée dans du sable d’une partie de la zone générale non tondue à hauteur du fairway ou moins.","o":[["Vérifier les critères puis prendre un dégagement gratuit","Oui. L’impact propre et la zone doivent être confirmés."],["La déplacer librement sans référence","Non. La procédure de dégagement est précise."],["Considérer toute balle difficile comme enfoncée","Non. Un mauvais lie ne suffit pas."]]},{"v":2,"p":"Une balle repose seulement au fond d’une touffe sans impact dans le sol. Est-elle forcément enfoncée au sens de la règle ?","i":"Balle partiellement sous le niveau du sol dans son propre impact sur le fairway. Une balle repose seulement au fond d’une touffe sans impact dans le sol. Est-elle forcément enfoncée au sens de la règle ?","x":"Une balle enfoncée dans son propre impact dans la zone générale peut généralement bénéficier d’un dégagement gratuit, sauf notamment si elle est enfoncée dans du sable d’une partie de la zone générale non tondue à hauteur du fairway ou moins.","o":[["Non, il faut un enfoncement dans son propre impact","Oui. Une touffe d’herbe difficile ne suffit pas."],["Oui, toute balle basse dans l’herbe est enfoncée","Non. Le niveau du sol et l’impact comptent."],["Oui, si elle est près du green","Non. La proximité du green ne définit pas l’enfoncement."]]}]},
  {"n":24,"r":"Définition « Point le plus proche de dégagement complet » ; Règle 16.1","s":"Le chemin artificiel gêne le swing de Zoé; le côté le plus proche est dans un rough épais.","e":"Le point le plus proche de dégagement complet est le point de référence le plus proche de la balle, dans la zone requise, sans interférence pour le coup prévu et sans se rapprocher du trou. Il n’est pas forcément le meilleur lie.","a":"Je simule stance et swing avec le club prévu, puis mesure la zone de drop à partir du bon point.","m":"Choisir le côté le plus agréable plutôt que le point réellement le plus proche.","c":"Placez deux points candidats et mesurez-les pour distinguer proche et favorable.","v":"Balle sur un chemin, deux points candidats dont un dans le rough.","q":[{"v":0,"p":"Le point le plus proche de dégagement complet est-il toujours le meilleur lie ?","i":"Balle sur un chemin, deux points candidats dont un dans le rough. Le point le plus proche de dégagement complet est-il toujours le meilleur lie ?","x":"Le point le plus proche de dégagement complet est le point de référence le plus proche de la balle, dans la zone requise, sans interférence pour le coup prévu et sans se rapprocher du trou. Il n’est pas forcément le meilleur lie.","o":[["Non, c’est le point conforme le plus proche","Oui. La qualité du lie ne décide pas du point."],["Oui, choisir le meilleur lie","Non. Ce choix libre n’est pas prévu."],["Toujours reculer de deux clubs","Non. Ce n’est pas la définition du point."]]},{"v":1,"p":"Deux côtés d’une allée offrent des lies différents. Comment choisir le point de référence ?","i":"Balle sur un chemin, deux points candidats dont un dans le rough. Deux côtés d’une allée offrent des lies différents. Comment choisir le point de référence ?","x":"Le point le plus proche de dégagement complet est le point de référence le plus proche de la balle, dans la zone requise, sans interférence pour le coup prévu et sans se rapprocher du trou. Il n’est pas forcément le meilleur lie.","o":[["Le point conforme réellement le plus proche","Oui. On mesure la distance, pas la qualité du lie."],["Le côté dont le gazon est le plus court","Non. Ce n’est pas le critère du point de référence."],["Toujours le côté gauche","Non. Il dépend de la position de la balle."]]},{"v":2,"p":"Le point le plus proche se trouve dans du rough. Peut-on préférer le fairway plus éloigné ?","i":"Balle sur un chemin, deux points candidats dont un dans le rough. Le point le plus proche se trouve dans du rough. Peut-on préférer le fairway plus éloigné ?","x":"Le point le plus proche de dégagement complet est le point de référence le plus proche de la balle, dans la zone requise, sans interférence pour le coup prévu et sans se rapprocher du trou. Il n’est pas forcément le meilleur lie.","o":[["Non, c’est le point conforme le plus proche","Oui. La qualité du lie ne décide pas du point."],["Oui, choisir le meilleur lie","Non. Ce choix libre n’est pas prévu."],["Toujours reculer de deux clubs","Non. Ce n’est pas la définition du point."]]}]}
  ,
  {"n":25,"r":"Définition « Zone à pénalité » ; Règle 17.1","s":"Au bord d’un étang, Chloé voit des piquets jaunes d’un côté et rouges de l’autre.","e":"Une zone à pénalité est définie par le Comité et marquée en jaune ou rouge; le rouge offre notamment une option latérale supplémentaire. Le bord extérieur des piquets ou de la ligne définit la limite.","a":"Je repère la couleur et la limite avant de choisir de jouer ou de prendre un dégagement.","m":"Croire que tous les plans d’eau offrent les mêmes options latérales.","c":"Marquez deux zones fictives rouge et jaune et faites comparer les options.","v":"Étang partagé en limite jaune et rouge clairement distinctes.","q":[{"v":0,"p":"Quelle couleur offre une option latérale supplémentaire de dégagement ?","i":"Étang partagé en limite jaune et rouge clairement distinctes. Quelle couleur offre une option latérale supplémentaire de dégagement ?","x":"Une zone à pénalité est définie par le Comité et marquée en jaune ou rouge; le rouge offre notamment une option latérale supplémentaire. Le bord extérieur des piquets ou de la ligne définit la limite.","o":[["Rouge","Oui. Le rouge offre normalement une option latérale supplémentaire."],["Jaune","Non. Une zone jaune n’offre pas l’option latérale ordinaire."],["Blanc","Non. Le blanc indique généralement le hors limites."]]},{"v":1,"p":"Une zone est marquée en jaune. Peut-on supposer une option latérale ordinaire ?","i":"Étang partagé en limite jaune et rouge clairement distinctes. Une zone est marquée en jaune. Peut-on supposer une option latérale ordinaire ?","x":"Une zone à pénalité est définie par le Comité et marquée en jaune ou rouge; le rouge offre notamment une option latérale supplémentaire. Le bord extérieur des piquets ou de la ligne définit la limite.","o":[["Non, le jaune n’offre pas l’option latérale ordinaire","Oui. Il reste coup et distance ou recul sur la ligne."],["Oui, toutes les couleurs sont identiques","Non. Le rouge ajoute une option."],["Oui, sans coup de pénalité","Non. Ce dégagement est pénalisé."]]},{"v":2,"p":"Une zone est marquée en rouge. Quelle option supplémentaire faut-il envisager ?","i":"Étang partagé en limite jaune et rouge clairement distinctes. Une zone est marquée en rouge. Quelle option supplémentaire faut-il envisager ?","x":"Une zone à pénalité est définie par le Comité et marquée en jaune ou rouge; le rouge offre notamment une option latérale supplémentaire. Le bord extérieur des piquets ou de la ligne définit la limite.","o":[["Le dégagement latéral","Oui. Le rouge ajoute normalement cette option."],["Un dégagement gratuit automatique","Non. Sortir de la zone coûte normalement un coup."],["Une balle provisoire dans l’eau","Non. Ce n’est pas l’option latérale."]]}]},
  {"n":26,"r":"Règle 17.1b-c","s":"La balle de Yanis repose sur une berge sèche à l’intérieur d’une zone rouge, sans zone de jeu interdit.","e":"Une balle dans une zone à pénalité peut être jouée comme elle repose sans pénalité, sous les mêmes règles générales de jeu, ou bénéficier d’un dégagement avec un coup. Une zone de jeu interdit est une exception.","a":"Je vérifie que le jeu n’est pas interdit et décide de jouer la balle sur place ou de prendre le dégagement autorisé.","m":"Croire qu’une balle dans une zone à pénalité doit toujours être droppée.","c":"Faites visualiser une balle jouable sur une berge sèche et une autre inaccessible.","v":"Balle sur une berge sèche entre des piquets rouges.","q":[{"v":0,"p":"Une balle jouable repose dans une zone rouge sans zone de jeu interdit. Peut-on la jouer ?","i":"Balle sur une berge sèche entre des piquets rouges. Une balle jouable repose dans une zone rouge sans zone de jeu interdit. Peut-on la jouer ?","x":"Une balle dans une zone à pénalité peut être jouée comme elle repose sans pénalité, sous les mêmes règles générales de jeu, ou bénéficier d’un dégagement avec un coup. Une zone de jeu interdit est une exception.","o":[["Jouer sur place si cela est permis","Oui. Le jeu direct est possible hors zone de jeu interdit."],["Dropper obligatoirement dans tous les cas","Non. Le dégagement pénalisé est une option."],["Déplacer la balle gratuitement hors de la zone","Non. Sortir par dégagement entraîne normalement un coup."]]},{"v":1,"p":"Dans une zone jaune, la balle de Zoé est visible sur l’herbe sèche. Quelle option sans pénalité ?","i":"Balle sur une berge sèche entre des piquets rouges. Dans une zone jaune, la balle de Zoé est visible sur l’herbe sèche. Quelle option sans pénalité ?","x":"Une balle dans une zone à pénalité peut être jouée comme elle repose sans pénalité, sous les mêmes règles générales de jeu, ou bénéficier d’un dégagement avec un coup. Une zone de jeu interdit est une exception.","o":[["Jouer sur place si cela est permis","Oui. Le jeu direct est possible hors zone de jeu interdit."],["Dropper obligatoirement dans tous les cas","Non. Le dégagement pénalisé est une option."],["Déplacer la balle gratuitement hors de la zone","Non. Sortir par dégagement entraîne normalement un coup."]]},{"v":2,"p":"Un panneau interdit de jouer dans une partie de la zone à pénalité. Peut-on choisir librement de jouer sur place ?","i":"Balle sur une berge sèche entre des piquets rouges. Un panneau interdit de jouer dans une partie de la zone à pénalité. Peut-on choisir librement de jouer sur place ?","x":"Une balle dans une zone à pénalité peut être jouée comme elle repose sans pénalité, sous les mêmes règles générales de jeu, ou bénéficier d’un dégagement avec un coup. Une zone de jeu interdit est une exception.","o":[["Non, la zone de jeu interdit impose un dégagement","Oui. On ne joue pas de cette partie de la zone."],["Oui, si la balle est sèche","Non. Le caractère sec ne lève pas l’interdiction."],["Oui, après un coup de pénalité joué sur place","Non. Il faut sortir selon la procédure."]]}]},
  {"n":27,"r":"Règle 17.1d ; définition « Zone à pénalité »","s":"La balle d’Emma traverse la limite rouge, rebondit sur la berge puis disparaît dans la zone.","e":"Pour les dégagements fondés sur l’entrée, le point de référence est le dernier endroit où la balle a franchi la limite de la zone à pénalité, non son point de chute final.","a":"Je retrace la trajectoire et estime avec les autres le dernier franchissement de la limite.","m":"Utiliser le point où la balle a disparu ou l’endroit le plus pratique.","c":"Tracez une limite et faites franchir une balle plusieurs fois pour trouver le dernier passage.","v":"Trajectoire d’une balle franchissant deux fois une ligne rouge près d’un étang.","q":[{"v":0,"p":"Une balle franchit deux fois la limite rouge. Quel franchissement compte pour le dégagement ?","i":"Trajectoire d’une balle franchissant deux fois une ligne rouge près d’un étang. Une balle franchit deux fois la limite rouge. Quel franchissement compte pour le dégagement ?","x":"Pour les dégagements fondés sur l’entrée, le point de référence est le dernier endroit où la balle a franchi la limite de la zone à pénalité, non son point de chute final.","o":[["Le dernier franchissement de la limite","Oui. C’est le point de référence pertinent."],["Le premier franchissement","Non. La balle a ensuite quitté puis réintégré la zone."],["Le point de chute dans l’eau","Non. Il ne définit pas la limite franchie."]]},{"v":1,"p":"La balle de Mia rebondit hors de la zone puis y revient. Où se situe le point de référence ?","i":"Trajectoire d’une balle franchissant deux fois une ligne rouge près d’un étang. La balle de Mia rebondit hors de la zone puis y revient. Où se situe le point de référence ?","x":"Pour les dégagements fondés sur l’entrée, le point de référence est le dernier endroit où la balle a franchi la limite de la zone à pénalité, non son point de chute final.","o":[["Le dernier franchissement de la limite","Oui. C’est le point de référence pertinent."],["Le premier franchissement","Non. La balle a ensuite quitté puis réintégré la zone."],["Le point de chute dans l’eau","Non. Il ne définit pas la limite franchie."]]},{"v":2,"p":"Le joueur voit sa balle tomber loin dans l’eau. Le point de chute remplace-t-il le dernier franchissement ?","i":"Trajectoire d’une balle franchissant deux fois une ligne rouge près d’un étang. Le joueur voit sa balle tomber loin dans l’eau. Le point de chute remplace-t-il le dernier franchissement ?","x":"Pour les dégagements fondés sur l’entrée, le point de référence est le dernier endroit où la balle a franchi la limite de la zone à pénalité, non son point de chute final.","o":[["Non, c’est le dernier franchissement","Oui. La chute finale ne sert pas de point de référence."],["Oui, le point de chute dans l’eau","Non. Il peut être loin de la limite."],["Oui, le premier franchissement du trou","Non. On utilise le dernier passage de la limite."]]}]},
  {"n":28,"r":"Règle 17.1d(1)-(2)","s":"La balle de Léo est dans une zone jaune et il préfère ne pas la jouer sur place.","e":"Pour un coup de pénalité, la zone jaune offre coup et distance ou dégagement en arrière sur la ligne passant par le trou et le dernier point d’entrée. Elle n’offre pas l’option latérale ordinaire du rouge.","a":"Je détermine le dernier point d’entrée puis choisis l’une des deux options prévues, en droppant correctement.","m":"Prendre automatiquement deux longueurs de club latérales pour une zone jaune.","c":"Avec un plan du trou, tracez la ligne trou-point d’entrée et le retour au coup précédent.","v":"Zone jaune, trou et dernier point d’entrée reliés par une ligne imaginaire.","q":[{"v":0,"p":"Quelles options ordinaires existent avec un coup pour une zone jaune ?","i":"Zone jaune, trou et dernier point d’entrée reliés par une ligne imaginaire. Quelles options ordinaires existent avec un coup pour une zone jaune ?","x":"Pour un coup de pénalité, la zone jaune offre coup et distance ou dégagement en arrière sur la ligne passant par le trou et le dernier point d’entrée. Elle n’offre pas l’option latérale ordinaire du rouge.","o":[["Coup et distance ou en arrière sur la ligne","Oui. Ce sont les deux options ordinaires du jaune."],["Toujours un drop latéral à deux clubs","Non. Cette option ordinaire est réservée au rouge."],["Un déplacement gratuit vers le fairway","Non. Le dégagement de zone entraîne un coup de pénalité."]]},{"v":1,"p":"La balle de Sara est perdue dans une zone jaune. Peut-elle dropper latéralement à deux clubs selon la seule règle de zone jaune ?","i":"Zone jaune, trou et dernier point d’entrée reliés par une ligne imaginaire. La balle de Sara est perdue dans une zone jaune. Peut-elle dropper latéralement à deux clubs selon la seule règle de zone jaune ?","x":"Pour un coup de pénalité, la zone jaune offre coup et distance ou dégagement en arrière sur la ligne passant par le trou et le dernier point d’entrée. Elle n’offre pas l’option latérale ordinaire du rouge.","o":[["Non, la zone jaune n’offre pas cette option ordinaire","Oui. Il faut choisir une des options prévues."],["Oui, depuis n’importe quel bord","Non. Ce dégagement latéral ordinaire est propre au rouge."],["Oui, gratuitement","Non. Le dégagement de zone est pénalisé."]]},{"v":2,"p":"Pour reculer sur la ligne d’une zone jaune, par quel point cette ligne passe-t-elle ?","i":"Zone jaune, trou et dernier point d’entrée reliés par une ligne imaginaire. Pour reculer sur la ligne d’une zone jaune, par quel point cette ligne passe-t-elle ?","x":"Pour un coup de pénalité, la zone jaune offre coup et distance ou dégagement en arrière sur la ligne passant par le trou et le dernier point d’entrée. Elle n’offre pas l’option latérale ordinaire du rouge.","o":[["Par le trou et le dernier point d’entrée","Oui. On prolonge cette ligne vers l’arrière."],["Par la balle et le départ uniquement","Non. Le trou et le point d’entrée définissent la ligne."],["Par le bord le plus proche du fairway","Non. Ce n’est pas la ligne réglementaire."]]}]},
  {"n":29,"r":"Règle 17.1d(3)","s":"La balle de Nora entre dans une zone rouge près d’un buisson et reste injouable.","e":"En plus des options de coup et distance et de ligne arrière, la zone rouge permet, avec un coup de pénalité, un dégagement latéral à deux longueurs de club du dernier point d’entrée, sans se rapprocher du trou et hors de la zone.","a":"Je localise le dernier franchissement et mesure deux longueurs de club pour la zone latérale.","m":"Mesurer depuis la balle dans la zone plutôt que depuis son dernier point d’entrée.","c":"Tracez une zone rouge et mesurez deux longueurs de club à partir de son bord.","v":"Balle dans une zone rouge et demi-cercle de deux clubs au point d’entrée.","q":[{"v":0,"p":"D’où mesure-t-on l’option latérale d’une zone rouge ?","i":"Balle dans une zone rouge et demi-cercle de deux clubs au point d’entrée. D’où mesure-t-on l’option latérale d’une zone rouge ?","x":"En plus des options de coup et distance et de ligne arrière, la zone rouge permet, avec un coup de pénalité, un dégagement latéral à deux longueurs de club du dernier point d’entrée, sans se rapprocher du trou et hors de la zone.","o":[["Du dernier point où la balle a franchi la limite","Oui. Ce point sert de référence au dégagement latéral."],["De la balle au fond de la zone","Non. Le point de référence est le franchissement."],["De l’endroit le plus proche du fairway","Non. On ne choisit pas librement le point."]]},{"v":1,"p":"Une balle disparaît dans une zone rouge. Quel point sert de référence aux deux clubs ?","i":"Balle dans une zone rouge et demi-cercle de deux clubs au point d’entrée. Une balle disparaît dans une zone rouge. Quel point sert de référence aux deux clubs ?","x":"En plus des options de coup et distance et de ligne arrière, la zone rouge permet, avec un coup de pénalité, un dégagement latéral à deux longueurs de club du dernier point d’entrée, sans se rapprocher du trou et hors de la zone.","o":[["Du dernier point où la balle a franchi la limite","Oui. Ce point sert de référence au dégagement latéral."],["De la balle au fond de la zone","Non. Le point de référence est le franchissement."],["De l’endroit le plus proche du fairway","Non. On ne choisit pas librement le point."]]},{"v":2,"p":"Nora veut utiliser l’option latérale rouge. Peut-elle mesurer depuis la balle arrêtée dans l’eau ?","i":"Balle dans une zone rouge et demi-cercle de deux clubs au point d’entrée. Nora veut utiliser l’option latérale rouge. Peut-elle mesurer depuis la balle arrêtée dans l’eau ?","x":"En plus des options de coup et distance et de ligne arrière, la zone rouge permet, avec un coup de pénalité, un dégagement latéral à deux longueurs de club du dernier point d’entrée, sans se rapprocher du trou et hors de la zone.","o":[["Non, depuis le dernier point d’entrée","Oui. La balle arrêtée dans l’eau n’est pas la référence latérale."],["Oui, depuis sa position finale","Non. Cette position n’est pas le point d’entrée."],["Oui, depuis le piquet le plus proche","Non. Le piquet ne remplace pas le franchissement."]]}]},
  {"n":30,"r":"Règles 15.1 et 17.1b","s":"Une feuille morte repose près de la balle de Tom dans une zone à pénalité sèche.","e":"Les détritus peuvent être enlevés dans une zone à pénalité. Mais si leur retrait déplace la balle au repos, la balle doit être replacée et une pénalité peut s’appliquer selon la Règle 9.4.","a":"Je retire prudemment le détritus sans déplacer la balle et vérifie le résultat.","m":"Croire que tout détritus est intouchable dans une zone à pénalité.","c":"Faites retirer une feuille puis une brindille très proche de la balle sans la bouger.","v":"Feuille morte à côté d’une balle dans une zone rouge sèche.","q":[{"v":0,"p":"Peux-tu enlever une feuille morte près de ta balle dans une zone rouge ?","i":"Feuille morte à côté d’une balle dans une zone rouge sèche. Peux-tu enlever une feuille morte près de ta balle dans une zone rouge ?","x":"Les détritus peuvent être enlevés dans une zone à pénalité. Mais si leur retrait déplace la balle au repos, la balle doit être replacée et une pénalité peut s’appliquer selon la Règle 9.4.","o":[["Oui, en évitant de déplacer la balle","Oui. Les détritus peuvent être retirés dans cette zone."],["Non, tout détritus y est interdit","Non. Cette ancienne restriction ne s’applique pas."],["Oui, et le déplacement de la balle est toujours ignoré","Non. Déplacer la balle peut entraîner replacement et pénalité."]]},{"v":1,"p":"Un petit caillou mobile gêne Mia dans une zone jaune. Peut-elle l’enlever ?","i":"Feuille morte à côté d’une balle dans une zone rouge sèche. Un petit caillou mobile gêne Mia dans une zone jaune. Peut-elle l’enlever ?","x":"Les détritus peuvent être enlevés dans une zone à pénalité. Mais si leur retrait déplace la balle au repos, la balle doit être replacée et une pénalité peut s’appliquer selon la Règle 9.4.","o":[["Oui, en évitant de déplacer la balle","Oui. Les détritus peuvent être retirés dans cette zone."],["Non, tout détritus y est interdit","Non. Cette ancienne restriction ne s’applique pas."],["Oui, et le déplacement de la balle est toujours ignoré","Non. Déplacer la balle peut entraîner replacement et pénalité."]]},{"v":2,"p":"En retirant une brindille dans une zone rouge, le joueur fait bouger sa balle. Quelle vérification doit-il faire ?","i":"Feuille morte à côté d’une balle dans une zone rouge sèche. En retirant une brindille dans une zone rouge, le joueur fait bouger sa balle. Quelle vérification doit-il faire ?","x":"Les détritus peuvent être enlevés dans une zone à pénalité. Mais si leur retrait déplace la balle au repos, la balle doit être replacée et une pénalité peut s’appliquer selon la Règle 9.4.","o":[["Replacer la balle et vérifier la pénalité applicable","Oui. Le retrait d’un détritus peut entraîner la Règle 9.4."],["Jouer la balle là où elle a roulé","Non. La balle déplacée se replace."],["Ignorer toujours le déplacement","Non. Une pénalité peut s’appliquer."]]}]}
  ,
  {"n":31,"r":"Définition « Hors limites » ; Règle 18.2a","s":"La balle de Chloé repose près de piquets blancs à la limite du terrain.","e":"Une balle n’est hors limites que si elle est entièrement au-delà du bord intérieur de la limite. Une partie de balle surplombant encore le parcours suffit pour qu’elle soit dans les limites.","a":"Je regarde la balle depuis le dessus et identifie la vraie ligne de limite.","m":"Déclarer hors limites une balle dont une partie reste dans le parcours.","c":"Tendez une ficelle entre les bords côté parcours des piquets et placez des balles sur la ligne.","v":"Balle blanche chevauchant la limite définie par deux piquets blancs.","q":[{"v":0,"p":"Une partie de la balle surplombe encore le parcours. Est-elle hors limites ?","i":"Balle blanche chevauchant la limite définie par deux piquets blancs. Une partie de la balle surplombe encore le parcours. Est-elle hors limites ?","x":"Une balle n’est hors limites que si elle est entièrement au-delà du bord intérieur de la limite. Une partie de balle surplombant encore le parcours suffit pour qu’elle soit dans les limites.","o":[["Elle reste dans les limites si une partie surplombe le parcours","Oui. Il faut que toute la balle soit au-delà pour être hors limites."],["La moitié suffit pour être hors limites","Non. Le critère est la balle entièrement au-delà."],["La position des pieds décide","Non. La limite concerne la balle."]]},{"v":1,"p":"La balle de Léa dépasse les piquets blancs mais chevauche la limite. Quel est son statut ?","i":"Balle blanche chevauchant la limite définie par deux piquets blancs. La balle de Léa dépasse les piquets blancs mais chevauche la limite. Quel est son statut ?","x":"Une balle n’est hors limites que si elle est entièrement au-delà du bord intérieur de la limite. Une partie de balle surplombant encore le parcours suffit pour qu’elle soit dans les limites.","o":[["Elle reste dans les limites si une partie surplombe le parcours","Oui. Il faut que toute la balle soit au-delà pour être hors limites."],["La moitié suffit pour être hors limites","Non. Le critère est la balle entièrement au-delà."],["La position des pieds décide","Non. La limite concerne la balle."]]},{"v":2,"p":"Toute la balle de Max repose au-delà de la limite blanche. Quel est son statut ?","i":"Balle blanche chevauchant la limite définie par deux piquets blancs. Toute la balle de Max repose au-delà de la limite blanche. Quel est son statut ?","x":"Une balle n’est hors limites que si elle est entièrement au-delà du bord intérieur de la limite. Une partie de balle surplombant encore le parcours suffit pour qu’elle soit dans les limites.","o":[["Elle est hors limites","Oui. Toute la balle repose au-delà de la limite."],["Elle reste en jeu car elle est proche","Non. La proximité ne suffit pas."],["Elle est dans une zone à pénalité","Non. Les piquets blancs définissent le hors limites."]]}]},
  {"n":32,"r":"Définition « Hors limites »","s":"Deux piquets blancs indiquent le bord extérieur d’un trou; Noé pense que la ligne passe par leur centre.","e":"Lorsque des piquets définissent le hors limites, la limite suit les points intérieurs au niveau du sol, côté parcours. Les piquets eux-mêmes sont hors limites et ne peuvent être déplacés comme des obstructions ordinaires.","a":"Je relie mentalement les faces intérieures des piquets au niveau du sol.","m":"Tracer la limite par l’extérieur des piquets ou les retirer pour faciliter le coup.","c":"Disposez deux piquets et une ficelle côté parcours pour observer les positions de balle.","v":"Deux piquets blancs avec une ligne reliant leurs faces intérieures au niveau du sol.","q":[{"v":0,"p":"Par quel côté des piquets blancs passe la limite hors limites ?","i":"Deux piquets blancs avec une ligne reliant leurs faces intérieures au niveau du sol. Par quel côté des piquets blancs passe la limite hors limites ?","x":"Lorsque des piquets définissent le hors limites, la limite suit les points intérieurs au niveau du sol, côté parcours. Les piquets eux-mêmes sont hors limites et ne peuvent être déplacés comme des obstructions ordinaires.","o":[["Par les faces intérieures côté parcours au sol","Oui. Ces points définissent la limite."],["Par le centre des piquets","Non. Leur axe n’est pas la limite."],["Par leurs faces extérieures","Non. Les piquets eux-mêmes sont hors limites."]]},{"v":1,"p":"Une balle est proche de deux piquets blancs. Quelle ligne faut-il imaginer ?","i":"Deux piquets blancs avec une ligne reliant leurs faces intérieures au niveau du sol. Une balle est proche de deux piquets blancs. Quelle ligne faut-il imaginer ?","x":"Lorsque des piquets définissent le hors limites, la limite suit les points intérieurs au niveau du sol, côté parcours. Les piquets eux-mêmes sont hors limites et ne peuvent être déplacés comme des obstructions ordinaires.","o":[["Par les faces intérieures côté parcours au sol","Oui. Ces points définissent la limite."],["Par le centre des piquets","Non. Leur axe n’est pas la limite."],["Par leurs faces extérieures","Non. Les piquets eux-mêmes sont hors limites."]]},{"v":2,"p":"Peut-on retirer un piquet blanc de limite pour faciliter le swing ?","i":"Deux piquets blancs avec une ligne reliant leurs faces intérieures au niveau du sol. Peut-on retirer un piquet blanc de limite pour faciliter le swing ?","x":"Lorsque des piquets définissent le hors limites, la limite suit les points intérieurs au niveau du sol, côté parcours. Les piquets eux-mêmes sont hors limites et ne peuvent être déplacés comme des obstructions ordinaires.","o":[["Non, c’est un objet de limite","Oui. Il ne se retire pas comme une obstruction mobile."],["Oui, s’il gêne le swing","Non. Une gêne ne rend pas le piquet amovible."],["Oui, s’il est remis après le coup","Non. Il ne faut pas le déplacer pour améliorer le coup."]]}]},
  {"n":33,"r":"Règle 18.1 ; Règle 14.6","s":"La balle de Mia est hors limites après son départ et elle doit poursuivre le trou.","e":"Coup et distance ajoute un coup de pénalité et impose de jouer de l’endroit du coup précédent. Si ce coup était joué depuis la zone de départ, la nouvelle balle peut être teed n’importe où dans cette zone.","a":"Je compte le coup joué et un coup de pénalité, puis je rejoue depuis la zone ou l’emplacement précédent selon le cas.","m":"Dropper près du point où la balle est sortie sans règle locale autorisant une autre procédure.","c":"Simulez un départ hors limites et faites compter les coups avant le coup suivant.","v":"Balle au-delà de piquets blancs et joueuse revenant au départ.","q":[{"v":0,"p":"Une balle jouée du départ est hors limites. Où joues-tu ensuite selon coup et distance ?","i":"Balle au-delà de piquets blancs et joueuse revenant au départ. Une balle jouée du départ est hors limites. Où joues-tu ensuite selon coup et distance ?","x":"Coup et distance ajoute un coup de pénalité et impose de jouer de l’endroit du coup précédent. Si ce coup était joué depuis la zone de départ, la nouvelle balle peut être teed n’importe où dans cette zone.","o":[["Rejouer de l’endroit du coup précédent avec un coup de pénalité","Oui. C’est le principe de coup et distance."],["Dropper gratuitement près de la limite","Non. Ce dégagement gratuit n’existe pas."],["Jouer une balle trouvée au-delà des limites","Non. Une balle hors limites n’est plus en jeu."]]},{"v":1,"p":"Une balle du fairway est perdue hors zone à pénalité. Quel endroit sert à rejouer ?","i":"Balle au-delà de piquets blancs et joueuse revenant au départ. Une balle du fairway est perdue hors zone à pénalité. Quel endroit sert à rejouer ?","x":"Coup et distance ajoute un coup de pénalité et impose de jouer de l’endroit du coup précédent. Si ce coup était joué depuis la zone de départ, la nouvelle balle peut être teed n’importe où dans cette zone.","o":[["Rejouer de l’endroit du coup précédent avec un coup de pénalité","Oui. C’est le principe de coup et distance."],["Dropper gratuitement près de la limite","Non. Ce dégagement gratuit n’existe pas."],["Jouer une balle trouvée au-delà des limites","Non. Une balle hors limites n’est plus en jeu."]]},{"v":2,"p":"Après une balle hors limites sans règle locale pertinente, peut-on simplement dropper près de la sortie ?","i":"Balle au-delà de piquets blancs et joueuse revenant au départ. Après une balle hors limites sans règle locale pertinente, peut-on simplement dropper près de la sortie ?","x":"Coup et distance ajoute un coup de pénalité et impose de jouer de l’endroit du coup précédent. Si ce coup était joué depuis la zone de départ, la nouvelle balle peut être teed n’importe où dans cette zone.","o":[["Non, il faut appliquer coup et distance","Oui. Sans règle locale applicable, le drop près de la sortie n’est pas prévu."],["Oui, gratuitement","Non. Le hors limites impose normalement un coup et distance."],["Oui, avec une seule longueur de club","Non. Cette zone n’existe pas sous la Règle 18."]]}]},
  {"n":34,"r":"Règle 18.3a-b","s":"Le départ de Sami part vers des arbres où sa balle pourrait être perdue hors zone à pénalité; il sort une seconde balle.","e":"Pour être provisoire, l’intention doit être annoncée clairement à quelqu’un avant le coup : dire « provisoire » ou une formule sans ambiguïté. « J’en joue une autre » ne suffit pas; exception pratique si personne n’est à proximité pour entendre.","a":"J’annonce « Je joue une balle provisoire » avant de la frapper.","m":"Annoncer seulement après le coup ou utiliser une phrase ambiguë.","c":"Faites dire l’annonce puis démarrez le mouvement de coup, jamais l’inverse.","v":"Joueur tenant une seconde balle et parlant à son groupe avant le coup.","q":[{"v":0,"p":"Quand faut-il annoncer la balle provisoire ?","i":"Joueur tenant une seconde balle et parlant à son groupe avant le coup. Quand faut-il annoncer la balle provisoire ?","x":"Pour être provisoire, l’intention doit être annoncée clairement à quelqu’un avant le coup : dire « provisoire » ou une formule sans ambiguïté. « J’en joue une autre » ne suffit pas; exception pratique si personne n’est à proximité pour entendre.","o":[["Avant le coup, en indiquant clairement « provisoire »","Oui. L’annonce explicite précède le coup."],["Après le coup seulement","Non. Il est alors trop tard pour ce coup."],["Ne rien dire si un partenaire est là","Non. Il faut annoncer à quelqu’un présent."]]},{"v":1,"p":"Noé dit « j’en remets une » avant de jouer. L’annonce est-elle assez claire ?","i":"Joueur tenant une seconde balle et parlant à son groupe avant le coup. Noé dit « j’en remets une » avant de jouer. L’annonce est-elle assez claire ?","x":"Pour être provisoire, l’intention doit être annoncée clairement à quelqu’un avant le coup : dire « provisoire » ou une formule sans ambiguïté. « J’en joue une autre » ne suffit pas; exception pratique si personne n’est à proximité pour entendre.","o":[["Non, il faut annoncer clairement « provisoire »","Oui. « J’en remets une » est ambigu."],["Oui, cette phrase suffit toujours","Non. Elle peut signifier coup et distance définitif."],["Oui, l’annonce peut attendre après le coup","Non. Elle doit précéder le coup."]]},{"v":2,"p":"Léa annonce clairement une provisoire après avoir déjà frappé la seconde balle. Est-ce à temps ?","i":"Joueur tenant une seconde balle et parlant à son groupe avant le coup. Léa annonce clairement une provisoire après avoir déjà frappé la seconde balle. Est-ce à temps ?","x":"Pour être provisoire, l’intention doit être annoncée clairement à quelqu’un avant le coup : dire « provisoire » ou une formule sans ambiguïté. « J’en joue une autre » ne suffit pas; exception pratique si personne n’est à proximité pour entendre.","o":[["Non, l’annonce doit précéder le coup","Oui. Après le coup, il est trop tard."],["Oui, tant que la recherche n’a pas commencé","Non. Le moment décisif est le coup."],["Oui, si le groupe accepte","Non. Le groupe ne peut pas changer cette exigence."]]}]},
  {"n":35,"r":"Règle 18.3c(2)","s":"La provisoire de Nora repose plus près du trou que l’endroit estimé de l’originale; elle s’apprête à la jouer.","e":"Une provisoire devient la balle en jeu si l’originale est perdue hors zone à pénalité ou hors limites, ou si la provisoire est jouée d’un endroit plus près du trou que la position estimée de l’originale.","a":"Je compare les positions estimées avant chaque coup de provisoire et arrête si l’originale est retrouvée à temps.","m":"Croire qu’une provisoire reste provisoire quel que soit l’endroit d’où on la joue.","c":"Placez deux repères de distance au trou et faites évoluer la provisoire.","v":"Deux balles à différentes distances du trou, provisoire plus proche que l’originale estimée.","q":[{"v":0,"p":"Quand une provisoire jouée devient-elle balle en jeu ?","i":"Deux balles à différentes distances du trou, provisoire plus proche que l’originale estimée. Quand une provisoire jouée devient-elle balle en jeu ?","x":"Une provisoire devient la balle en jeu si l’originale est perdue hors zone à pénalité ou hors limites, ou si la provisoire est jouée d’un endroit plus près du trou que la position estimée de l’originale.","o":[["Quand l’originale est perdue/hors limites ou qu’elle est jouée plus près","Oui. Ces situations font basculer le statut."],["Dès que la provisoire est posée sur un tee","Non. Elle reste provisoire après le coup initial."],["Seulement avec accord du groupe","Non. Le statut résulte de la règle."]]},{"v":1,"p":"La provisoire de Max est jouée d’un endroit plus près du trou que l’originale estimée. Quel effet ?","i":"Deux balles à différentes distances du trou, provisoire plus proche que l’originale estimée. La provisoire de Max est jouée d’un endroit plus près du trou que l’originale estimée. Quel effet ?","x":"Une provisoire devient la balle en jeu si l’originale est perdue hors zone à pénalité ou hors limites, ou si la provisoire est jouée d’un endroit plus près du trou que la position estimée de l’originale.","o":[["Elle devient la balle en jeu","Oui. Jouer la provisoire plus près du trou déclenche ce statut."],["Elle reste toujours provisoire","Non. Sa position jouée change son statut."],["Les deux balles restent en jeu","Non. L’originale n’est alors plus en jeu."]]},{"v":2,"p":"L’originale est hors limites. Quel statut prend la provisoire annoncée ?","i":"Deux balles à différentes distances du trou, provisoire plus proche que l’originale estimée. L’originale est hors limites. Quel statut prend la provisoire annoncée ?","x":"Une provisoire devient la balle en jeu si l’originale est perdue hors zone à pénalité ou hors limites, ou si la provisoire est jouée d’un endroit plus près du trou que la position estimée de l’originale.","o":[["Elle devient la balle en jeu","Oui. L’originale hors limites ne peut plus être jouée."],["Elle doit être abandonnée","Non. Elle prend la place de l’originale."],["Elle reste une balle d’entraînement","Non. Elle est jouée sous la Règle 18.3."]]}]},
  {"n":36,"r":"Règle 18.3c(3)","s":"Zoé a joué une provisoire depuis un endroit encore plus éloigné du trou que l’originale estimée, puis retrouve l’originale à temps hors zone à pénalité.","e":"Si l’originale est trouvée sur le parcours hors zone à pénalité avant la fin des trois minutes et que la provisoire n’est pas devenue balle en jeu, cette dernière est abandonnée; ses coups ne comptent pas.","a":"Je vérifie le délai et le lieu, j’abandonne la provisoire et joue l’originale.","m":"Continuer la provisoire par préférence alors que l’originale est retrouvée à temps.","c":"Mettez une balle originale sous une feuille et retrouvez-la avant/après la limite de temps.","v":"Joueur retrouvant sa balle originale dans le rough avec provisoire plus loin.","q":[{"v":0,"p":"L’originale est retrouvée à temps hors zone à pénalité; la provisoire est encore provisoire. Que faire ?","i":"Joueur retrouvant sa balle originale dans le rough avec provisoire plus loin. L’originale est retrouvée à temps hors zone à pénalité; la provisoire est encore provisoire. Que faire ?","x":"Si l’originale est trouvée sur le parcours hors zone à pénalité avant la fin des trois minutes et que la provisoire n’est pas devenue balle en jeu, cette dernière est abandonnée; ses coups ne comptent pas.","o":[["Abandonner la provisoire et jouer l’originale","Oui. Les coups de la provisoire abandonnée ne comptent pas."],["Choisir la balle la plus favorable","Non. Le choix n’est pas libre."],["Jouer les deux balles jusqu’au green","Non. La provisoire abandonnée serait une mauvaise balle."]]},{"v":1,"p":"La balle originale de Mia est identifiée après deux minutes et la provisoire n’est pas devenue balle en jeu. Laquelle joue-t-elle ?","i":"Joueur retrouvant sa balle originale dans le rough avec provisoire plus loin. La balle originale de Mia est identifiée après deux minutes et la provisoire n’est pas devenue balle en jeu. Laquelle joue-t-elle ?","x":"Si l’originale est trouvée sur le parcours hors zone à pénalité avant la fin des trois minutes et que la provisoire n’est pas devenue balle en jeu, cette dernière est abandonnée; ses coups ne comptent pas.","o":[["Abandonner la provisoire et jouer l’originale","Oui. Les coups de la provisoire abandonnée ne comptent pas."],["Choisir la balle la plus favorable","Non. Le choix n’est pas libre."],["Jouer les deux balles jusqu’au green","Non. La provisoire abandonnée serait une mauvaise balle."]]},{"v":2,"p":"Peut-on choisir sa provisoire parce qu’elle est mieux placée si l’originale est retrouvée à temps ?","i":"Joueur retrouvant sa balle originale dans le rough avec provisoire plus loin. Peut-on choisir sa provisoire parce qu’elle est mieux placée si l’originale est retrouvée à temps ?","x":"Si l’originale est trouvée sur le parcours hors zone à pénalité avant la fin des trois minutes et que la provisoire n’est pas devenue balle en jeu, cette dernière est abandonnée; ses coups ne comptent pas.","o":[["Non, il faut abandonner la provisoire","Oui. L’originale retrouvée à temps doit être jouée."],["Oui, si elle est mieux placée","Non. La préférence n’est pas un critère."],["Oui, en ajoutant un coup","Non. La provisoire doit être abandonnée."]]}]}
  ,
  {"n":37,"r":"Règles 12.2a et 15.1","s":"Une feuille sèche repose près de la balle de Léa dans un bunker.","e":"Les détritus, comme les feuilles ou petites pierres libres, peuvent être retirés du bunker. Si cela déplace la balle, elle doit être replacée et une pénalité peut suivre selon la règle applicable.","a":"Je retire avec soin le détritus sans faire bouger la balle.","m":"Croire qu’il est toujours interdit de toucher les détritus du bunker.","c":"Posez une feuille à des distances variées de la balle et testez le geste.","v":"Feuille sèche près d’une balle dans le sable d’un bunker.","q":[{"v":0,"p":"Peux-tu enlever une feuille sèche dans un bunker ?","i":"Feuille sèche près d’une balle dans le sable d’un bunker. Peux-tu enlever une feuille sèche dans un bunker ?","x":"Les détritus, comme les feuilles ou petites pierres libres, peuvent être retirés du bunker. Si cela déplace la balle, elle doit être replacée et une pénalité peut suivre selon la règle applicable.","o":[["Oui, avec précaution pour ne pas déplacer la balle","Oui. Les détritus peuvent être retirés."],["Non, aucun objet naturel ne peut être retiré","Non. La règle l’autorise."],["Oui, et la balle déplacée se joue au nouvel endroit","Non. Si elle bouge, elle doit être replacée."]]},{"v":1,"p":"Un petit caillou libre gêne le coup d’Emma dans le bunker. Peut-elle l’enlever ?","i":"Feuille sèche près d’une balle dans le sable d’un bunker. Un petit caillou libre gêne le coup d’Emma dans le bunker. Peut-elle l’enlever ?","x":"Les détritus, comme les feuilles ou petites pierres libres, peuvent être retirés du bunker. Si cela déplace la balle, elle doit être replacée et une pénalité peut suivre selon la règle applicable.","o":[["Oui, avec précaution pour ne pas déplacer la balle","Oui. Les détritus peuvent être retirés."],["Non, aucun objet naturel ne peut être retiré","Non. La règle l’autorise."],["Oui, et la balle déplacée se joue au nouvel endroit","Non. Si elle bouge, elle doit être replacée."]]},{"v":2,"p":"Une brindille libre repose près de la balle de Max dans un bunker. Quelle précaution ?","i":"Feuille sèche près d’une balle dans le sable d’un bunker. Une brindille libre repose près de la balle de Max dans un bunker. Quelle précaution ?","x":"Les détritus, comme les feuilles ou petites pierres libres, peuvent être retirés du bunker. Si cela déplace la balle, elle doit être replacée et une pénalité peut suivre selon la règle applicable.","o":[["Oui, avec précaution pour ne pas déplacer la balle","Oui. Les détritus peuvent être retirés."],["Non, aucun objet naturel ne peut être retiré","Non. La règle l’autorise."],["Oui, et la balle déplacée se joue au nouvel endroit","Non. Si elle bouge, elle doit être replacée."]]}]},
  {"n":38,"r":"Règle 12.2b(2) ; Règle 8.1a","s":"En entrant dans le bunker, Ana touche accidentellement le sable avec son club loin de la balle.","e":"Toucher le sable n’est pas toujours pénalisé : certaines actions, dont poser un club ou garder l’équilibre, sont permises. Il ne faut toutefois ni tester volontairement le sable, ni toucher le sable avec le club juste devant ou derrière la balle, dans un essai ou dans le backswing, ni améliorer les conditions.","a":"Je vérifie où et pourquoi le sable a été touché avant de conclure.","m":"Traiter tout contact avec le sable comme une pénalité automatique.","c":"Comparez trois gestes : poser un club, tester le sable et toucher derrière la balle.","v":"Club reposant sur le sable loin d’une balle dans un bunker.","q":[{"v":0,"p":"Tout contact accidentel avec le sable loin de la balle est-il pénalisé ?","i":"Club reposant sur le sable loin d’une balle dans un bunker. Tout contact accidentel avec le sable loin de la balle est-il pénalisé ?","x":"Toucher le sable n’est pas toujours pénalisé : certaines actions, dont poser un club ou garder l’équilibre, sont permises. Il ne faut toutefois ni tester volontairement le sable, ni toucher le sable avec le club juste devant ou derrière la balle, dans un essai ou dans le backswing, ni améliorer les conditions.","o":[["Non, il faut examiner le geste et son effet","Oui. Certaines façons de toucher le sable sont permises."],["Oui, toujours","Non. L’interdiction est ciblée."],["Le sable peut toujours être testé volontairement","Non. Tester son état avant le coup est interdit."]]},{"v":1,"p":"Léa pose son club dans le bunker loin de la balle sans améliorer son coup. Que vérifier ?","i":"Club reposant sur le sable loin d’une balle dans un bunker. Léa pose son club dans le bunker loin de la balle sans améliorer son coup. Que vérifier ?","x":"Toucher le sable n’est pas toujours pénalisé : certaines actions, dont poser un club ou garder l’équilibre, sont permises. Il ne faut toutefois ni tester volontairement le sable, ni toucher le sable avec le club juste devant ou derrière la balle, dans un essai ou dans le backswing, ni améliorer les conditions.","o":[["Vérifier si elle testait le sable ou améliorait le coup","Oui. Poser simplement le club loin de la balle peut être permis."],["Ajouter automatiquement deux coups","Non. Tout contact n’est pas interdit."],["Déclarer la balle perdue","Non. La balle est présente."]]},{"v":2,"p":"En perdant l’équilibre, Tom appuie sa main sur le sable sans améliorer son lie. Est-ce nécessairement une infraction ?","i":"Club reposant sur le sable loin d’une balle dans un bunker. En perdant l’équilibre, Tom appuie sa main sur le sable sans améliorer son lie. Est-ce nécessairement une infraction ?","x":"Toucher le sable n’est pas toujours pénalisé : certaines actions, dont poser un club ou garder l’équilibre, sont permises. Il ne faut toutefois ni tester volontairement le sable, ni toucher le sable avec le club juste devant ou derrière la balle, dans un essai ou dans le backswing, ni améliorer les conditions.","o":[["Non, ce contact peut être permis","Oui. Garder l’équilibre est une action autorisée si elle n’améliore pas le coup."],["Oui, tout contact entraîne une pénalité","Non. La règle distingue plusieurs gestes."],["Oui, la balle doit être droppée","Non. Le contact ne crée pas un dégagement."]]}]},
  {"n":39,"r":"Règle 12.2b(1)","s":"Avant son coup, Hugo enfonce volontairement la main dans le sable du bunker pour sentir sa texture.","e":"Tester délibérément l’état du sable pour obtenir une information sur le prochain coup est interdit et entraîne la pénalité générale.","a":"Je n’effectue aucun test du sable avec la main, le club, le râteau ou un objet.","m":"Confondre poser un club et enfoncer volontairement le club pour tester le sable.","c":"Demandez aux juniors d’expliquer l’intention derrière chaque geste près de la balle.","v":"Main pressant volontairement le sable dans un bunker avant le coup.","q":[{"v":0,"p":"Peux-tu tâter le sable pour prévoir ton prochain coup ?","i":"Main pressant volontairement le sable dans un bunker avant le coup. Peux-tu tâter le sable pour prévoir ton prochain coup ?","x":"Tester délibérément l’état du sable pour obtenir une information sur le prochain coup est interdit et entraîne la pénalité générale.","o":[["Non, tester volontairement le sable est interdit","Oui. Le test donne une information non autorisée."],["Oui, si la balle ne bouge pas","Non. L’interdiction ne dépend pas d’un déplacement."],["Oui, à plus d’une longueur de club","Non. Tester le sable du bunker est interdit avant le coup."]]},{"v":1,"p":"Nora racle le sable avec son club pour savoir s’il est humide. Est-ce permis ?","i":"Main pressant volontairement le sable dans un bunker avant le coup. Nora racle le sable avec son club pour savoir s’il est humide. Est-ce permis ?","x":"Tester délibérément l’état du sable pour obtenir une information sur le prochain coup est interdit et entraîne la pénalité générale.","o":[["Non, tester volontairement le sable est interdit","Oui. Le test donne une information non autorisée."],["Oui, si la balle ne bouge pas","Non. L’interdiction ne dépend pas d’un déplacement."],["Oui, à plus d’une longueur de club","Non. Tester le sable du bunker est interdit avant le coup."]]},{"v":2,"p":"Sami plante un râteau dans le sable pour apprendre sa fermeté avant de jouer. Quelle règle ?","i":"Main pressant volontairement le sable dans un bunker avant le coup. Sami plante un râteau dans le sable pour apprendre sa fermeté avant de jouer. Quelle règle ?","x":"Tester délibérément l’état du sable pour obtenir une information sur le prochain coup est interdit et entraîne la pénalité générale.","o":[["Tester volontairement le sable est interdit","Oui. Le râteau peut aussi servir à obtenir une information interdite."],["C’est permis si le râteau est au club","Non. Le propriétaire de l’objet est sans effet."],["C’est permis tant que la balle ne bouge pas","Non. L’interdiction vise le test lui-même."]]}]},
  {"n":40,"r":"Règle 19.3a","s":"La balle d’Inès est coincée sous la lèvre d’un bunker et elle la juge injouable.","e":"Pour une balle injouable dans un bunker, le joueur peut choisir coup et distance avec un coup, ou dégagement sur la ligne ou latéral avec un coup en restant dans le bunker. Une option supplémentaire permet de sortir sur la ligne avec deux coups au total.","a":"Je détermine l’option choisie et vérifie si la balle doit rester dans le bunker.","m":"Dropper juste à côté du bunker avec un seul coup en utilisant la procédure latérale.","c":"Tracez les trois options à un coup et celle à deux coups sur un plan.","v":"Balle sous la lèvre d’un bunker avec différentes zones de dégagement.","q":[{"v":0,"p":"Pour une balle injouable dans un bunker, le dégagement latéral à un coup reste où ?","i":"Balle sous la lèvre d’un bunker avec différentes zones de dégagement. Pour une balle injouable dans un bunker, le dégagement latéral à un coup reste où ?","x":"Pour une balle injouable dans un bunker, le joueur peut choisir coup et distance avec un coup, ou dégagement sur la ligne ou latéral avec un coup en restant dans le bunker. Une option supplémentaire permet de sortir sur la ligne avec deux coups au total.","o":[["Dans le bunker","Oui. Les options latérale et sur la ligne à un coup y restent."],["N’importe où hors du bunker","Non. L’option de sortie sur la ligne coûte deux coups au total."],["Toujours sur le green","Non. La zone de dégagement est définie par la règle."]]},{"v":1,"p":"Inès choisit le recul sur la ligne avec un coup. Sa balle doit reposer où ?","i":"Balle sous la lèvre d’un bunker avec différentes zones de dégagement. Inès choisit le recul sur la ligne avec un coup. Sa balle doit reposer où ?","x":"Pour une balle injouable dans un bunker, le joueur peut choisir coup et distance avec un coup, ou dégagement sur la ligne ou latéral avec un coup en restant dans le bunker. Une option supplémentaire permet de sortir sur la ligne avec deux coups au total.","o":[["Dans le bunker","Oui. Les options latérale et sur la ligne à un coup y restent."],["N’importe où hors du bunker","Non. L’option de sortie sur la ligne coûte deux coups au total."],["Toujours sur le green","Non. La zone de dégagement est définie par la règle."]]},{"v":2,"p":"Le dégagement latéral d’une balle injouable peut-il sortir du bunker pour un seul coup ?","i":"Balle sous la lèvre d’un bunker avec différentes zones de dégagement. Le dégagement latéral d’une balle injouable peut-il sortir du bunker pour un seul coup ?","x":"Pour une balle injouable dans un bunker, le joueur peut choisir coup et distance avec un coup, ou dégagement sur la ligne ou latéral avec un coup en restant dans le bunker. Une option supplémentaire permet de sortir sur la ligne avec deux coups au total.","o":[["Non, ce dégagement à un coup reste dans le bunker","Oui. La sortie spéciale sur la ligne coûte deux coups."],["Oui, si la zone latérale dépasse le bord","Non. La balle doit rester dans le bunker pour cette option."],["Oui, sans pénalité","Non. L’injouable est pénalisé."]]}]},
  {"n":41,"r":"Règle 19.3b","s":"Une balle injouable reste dans le bunker et Max préfère reculer hors du sable sur la ligne trou-balle.","e":"L’option supplémentaire de balle injouable en bunker permet de dropper en arrière sur la ligne hors du bunker pour un total de deux coups de pénalité. Il ne s’agit pas d’un drop latéral libre.","a":"Je trace la ligne du trou à la balle, recule jusqu’à sortir du bunker et compte deux coups de pénalité au total.","m":"Compter seulement un coup pour cette option de sortie du bunker.","c":"Matérialisez la ligne avec une corde et faites compter les deux coups.","v":"Ligne du trou traversant une balle de bunker puis s’étendant hors du sable.","q":[{"v":0,"p":"Combien de coups de pénalité pour sortir en arrière sur la ligne du bunker avec la Règle 19.3b ?","i":"Ligne du trou traversant une balle de bunker puis s’étendant hors du sable. Combien de coups de pénalité pour sortir en arrière sur la ligne du bunker avec la Règle 19.3b ?","x":"L’option supplémentaire de balle injouable en bunker permet de dropper en arrière sur la ligne hors du bunker pour un total de deux coups de pénalité. Il ne s’agit pas d’un drop latéral libre.","o":[["Deux coups de pénalité au total sur la ligne arrière","Oui. C’est l’option supplémentaire hors bunker."],["Un seul coup pour toute sortie du bunker","Non. La sortie sur cette ligne coûte deux coups."],["Aucun coup si la balle est injouable","Non. L’injouable est un dégagement pénalisé."]]},{"v":1,"p":"Une balle est injouable dans le sable; Léa choisit la ligne arrière hors bunker. Quel coût ?","i":"Ligne du trou traversant une balle de bunker puis s’étendant hors du sable. Une balle est injouable dans le sable; Léa choisit la ligne arrière hors bunker. Quel coût ?","x":"L’option supplémentaire de balle injouable en bunker permet de dropper en arrière sur la ligne hors du bunker pour un total de deux coups de pénalité. Il ne s’agit pas d’un drop latéral libre.","o":[["Deux coups de pénalité au total sur la ligne arrière","Oui. C’est l’option supplémentaire hors bunker."],["Un seul coup pour toute sortie du bunker","Non. La sortie sur cette ligne coûte deux coups."],["Aucun coup si la balle est injouable","Non. L’injouable est un dégagement pénalisé."]]},{"v":2,"p":"Max veut dropper latéralement hors du bunker avec seulement un coup. Est-ce l’option spéciale prévue ?","i":"Ligne du trou traversant une balle de bunker puis s’étendant hors du sable. Max veut dropper latéralement hors du bunker avec seulement un coup. Est-ce l’option spéciale prévue ?","x":"L’option supplémentaire de balle injouable en bunker permet de dropper en arrière sur la ligne hors du bunker pour un total de deux coups de pénalité. Il ne s’agit pas d’un drop latéral libre.","o":[["Non, la sortie spéciale est sur la ligne avec deux coups","Oui. Il ne s’agit pas d’une option latérale à un coup."],["Oui, toute sortie latérale coûte un coup","Non. Cette option n’existe pas."],["Oui, si la balle est près du bord","Non. La proximité du bord ne change pas la règle."]]}]},
  {"n":42,"r":"Règle 16.1c","s":"La balle de Zoé repose dans de l’eau temporaire au fond d’un bunker.","e":"Un dégagement gratuit complet est possible dans le bunker, au point le plus proche s’il existe; si aucun point complet n’existe, une option gratuite de dégagement maximum dans le bunker peut s’appliquer. Une sortie sur la ligne hors du bunker coûte un coup de pénalité.","a":"Je cherche d’abord un endroit adapté dans le bunker avant d’envisager la sortie pénalisée.","m":"Croire que toute eau temporaire permet de dropper gratuitement hors du bunker.","c":"Montrez un bunker partiellement puis entièrement inondé et comparez les options.","v":"Flaque temporaire au fond d’un bunker, zone sèche sur un côté.","q":[{"v":0,"p":"Une zone sèche permet un dégagement complet dans le bunker. Quel coût ?","i":"Flaque temporaire au fond d’un bunker, zone sèche sur un côté. Une zone sèche permet un dégagement complet dans le bunker. Quel coût ?","x":"Un dégagement gratuit complet est possible dans le bunker, au point le plus proche s’il existe; si aucun point complet n’existe, une option gratuite de dégagement maximum dans le bunker peut s’appliquer. Une sortie sur la ligne hors du bunker coûte un coup de pénalité.","o":[["Dans le bunker sans pénalité selon la procédure","Oui. Le dégagement gratuit reste dans le bunker."],["Hors du bunker sans pénalité","Non. La sortie sur la ligne coûte un coup."],["Déclarer obligatoirement la balle perdue","Non. La balle est présente et la Règle 16.1c donne des options."]]},{"v":1,"p":"La balle de Mia est dans l’eau temporaire d’un bunker. Peut-elle toujours sortir sans pénalité ?","i":"Flaque temporaire au fond d’un bunker, zone sèche sur un côté. La balle de Mia est dans l’eau temporaire d’un bunker. Peut-elle toujours sortir sans pénalité ?","x":"Un dégagement gratuit complet est possible dans le bunker, au point le plus proche s’il existe; si aucun point complet n’existe, une option gratuite de dégagement maximum dans le bunker peut s’appliquer. Une sortie sur la ligne hors du bunker coûte un coup de pénalité.","o":[["Non, le dégagement gratuit reste dans le bunker","Oui. Une sortie sur la ligne coûte un coup."],["Oui, toute eau permet une sortie gratuite","Non. Le bunker a ses propres limites."],["Oui, si toute la zone est inondée","Non. Une option gratuite de maximum reste dans le bunker."]]},{"v":2,"p":"Un bunker est inondé; quel lieu doit-on examiner pour un dégagement gratuit ou maximum ?","i":"Flaque temporaire au fond d’un bunker, zone sèche sur un côté. Un bunker est inondé; quel lieu doit-on examiner pour un dégagement gratuit ou maximum ?","x":"Un dégagement gratuit complet est possible dans le bunker, au point le plus proche s’il existe; si aucun point complet n’existe, une option gratuite de dégagement maximum dans le bunker peut s’appliquer. Une sortie sur la ligne hors du bunker coûte un coup de pénalité.","o":[["Dans le bunker, pour un dégagement maximum","Oui. Si aucun point complet n’existe, on examine le maximum dans le bunker."],["Sur le fairway sans pénalité","Non. La sortie hors du bunker sur la ligne coûte un coup."],["Au départ uniquement","Non. La Règle 16.1c prévoit d’autres options."]]}]}
  ,
  {"n":43,"r":"Règle 14.1a ; Règle 13.1b","s":"Sur le green, Inès veut relever sa balle pour laisser putter son partenaire.","e":"Avant de relever une balle qui devra être replacée, son emplacement doit être marqué avec un marque-balle ou un club posé juste derrière ou près de la balle. Elle est ensuite replacée au même point.","a":"Je marque d’abord, je relève puis replace la balle au point marqué.","m":"Relever sans marquer parce que la balle est visible.","c":"Faites pratiquer marque, relève et replacement sur trois pentes du green.","v":"Main posant un marque-balle derrière une balle sur le green.","q":[{"v":0,"p":"Que fais-tu avant de relever ta balle sur le green pour la replacer ?","i":"Main posant un marque-balle derrière une balle sur le green. Que fais-tu avant de relever ta balle sur le green pour la replacer ?","x":"Avant de relever une balle qui devra être replacée, son emplacement doit être marqué avec un marque-balle ou un club posé juste derrière ou près de la balle. Elle est ensuite replacée au même point.","o":[["Marquer l’emplacement","Oui. Il permettra de replacer au point initial."],["La lancer sur le côté sans repère","Non. Le replacement exige de connaître le point."],["Dropper près du trou","Non. La balle doit être replacée."]]},{"v":1,"p":"Max ramasse sa balle sur le green pour la nettoyer. Quel geste précède le relèvement ?","i":"Main posant un marque-balle derrière une balle sur le green. Max ramasse sa balle sur le green pour la nettoyer. Quel geste précède le relèvement ?","x":"Avant de relever une balle qui devra être replacée, son emplacement doit être marqué avec un marque-balle ou un club posé juste derrière ou près de la balle. Elle est ensuite replacée au même point.","o":[["Marquer l’emplacement","Oui. Il permettra de replacer au point initial."],["La lancer sur le côté sans repère","Non. Le replacement exige de connaître le point."],["Dropper près du trou","Non. La balle doit être replacée."]]},{"v":2,"p":"Zoé veut écarter sa balle de la ligne d’un partenaire. Que doit-elle faire d’abord ?","i":"Main posant un marque-balle derrière une balle sur le green. Zoé veut écarter sa balle de la ligne d’un partenaire. Que doit-elle faire d’abord ?","x":"Avant de relever une balle qui devra être replacée, son emplacement doit être marqué avec un marque-balle ou un club posé juste derrière ou près de la balle. Elle est ensuite replacée au même point.","o":[["Marquer l’emplacement","Oui. Il permettra de replacer au point initial."],["La lancer sur le côté sans repère","Non. Le replacement exige de connaître le point."],["Dropper près du trou","Non. La balle doit être replacée."]]}]},
  {"n":44,"r":"Règles 13.1b et 14.1c","s":"La balle de Léa sur le green a une trace de terre et elle veut la nettoyer avant son putt.","e":"Une balle sur le green peut être marquée, relevée, nettoyée et replacée à son emplacement d’origine.","a":"Je marque la position, relève, nettoie puis replace la même balle.","m":"Nettoyer en déplaçant la balle sans marquer sa place.","c":"Utilisez un marque-balle et une serviette pour rejouer toute la séquence.","v":"Balle marquée et nettoyée avec une serviette sur le green.","q":[{"v":0,"p":"Peut-on nettoyer une balle relevée du green après l’avoir marquée ?","i":"Balle marquée et nettoyée avec une serviette sur le green. Peut-on nettoyer une balle relevée du green après l’avoir marquée ?","x":"Une balle sur le green peut être marquée, relevée, nettoyée et replacée à son emplacement d’origine.","o":[["Oui, puis la replacer au point marqué","Oui. Le nettoyage est permis sur le green."],["Non, le nettoyage est toujours interdit","Non. Le green est une exception importante."],["Oui, puis la dropper ailleurs","Non. La balle est replacée à son point initial."]]},{"v":1,"p":"Noé relève une balle boueuse du green et la nettoie. Quelle suite ?","i":"Balle marquée et nettoyée avec une serviette sur le green. Noé relève une balle boueuse du green et la nettoie. Quelle suite ?","x":"Une balle sur le green peut être marquée, relevée, nettoyée et replacée à son emplacement d’origine.","o":[["Oui, puis la replacer au point marqué","Oui. Le nettoyage est permis sur le green."],["Non, le nettoyage est toujours interdit","Non. Le green est une exception importante."],["Oui, puis la dropper ailleurs","Non. La balle est replacée à son point initial."]]},{"v":2,"p":"La balle de Mia est sur le green. Quelle procédure permet de la nettoyer ?","i":"Balle marquée et nettoyée avec une serviette sur le green. La balle de Mia est sur le green. Quelle procédure permet de la nettoyer ?","x":"Une balle sur le green peut être marquée, relevée, nettoyée et replacée à son emplacement d’origine.","o":[["Oui, puis la replacer au point marqué","Oui. Le nettoyage est permis sur le green."],["Non, le nettoyage est toujours interdit","Non. Le green est une exception importante."],["Oui, puis la dropper ailleurs","Non. La balle est replacée à son point initial."]]}]},
  {"n":45,"r":"Règle 13.1c(2)","s":"Une marque d’impact de balle se trouve sur la ligne de putt d’Ana.","e":"Les dommages au green, dont les marques d’impact, peuvent être réparés raisonnablement pour retrouver autant que possible leur état initial, sans retarder déraisonnablement le jeu. Une usure naturelle ou simple imperfection n’est pas forcément un dommage réparable.","a":"Je répare délicatement la marque avec un outil normal sans créer un chemin amélioré.","m":"Creuser une rigole vers le trou sous prétexte de réparation.","c":"Montrez un impact récent et une zone usée naturellement pour comparer.","v":"Marque d’impact sur le green réparée avec un relève-pitch.","q":[{"v":0,"p":"Peut-on réparer une marque d’impact sur le green ?","i":"Marque d’impact sur le green réparée avec un relève-pitch. Peut-on réparer une marque d’impact sur le green ?","x":"Les dommages au green, dont les marques d’impact, peuvent être réparés raisonnablement pour retrouver autant que possible leur état initial, sans retarder déraisonnablement le jeu. Une usure naturelle ou simple imperfection n’est pas forcément un dommage réparable.","o":[["Oui, raisonnablement pour restaurer le green","Oui. Les dommages peuvent être réparés."],["Non, jamais avant le putt","Non. La réparation est autorisée."],["Oui, en modifiant librement la pente","Non. Il faut restaurer, pas améliorer au-delà de l’état initial."]]},{"v":1,"p":"Une marque de crampon gêne le putt de Léa. Quel geste raisonnable est permis ?","i":"Marque d’impact sur le green réparée avec un relève-pitch. Une marque de crampon gêne le putt de Léa. Quel geste raisonnable est permis ?","x":"Les dommages au green, dont les marques d’impact, peuvent être réparés raisonnablement pour retrouver autant que possible leur état initial, sans retarder déraisonnablement le jeu. Une usure naturelle ou simple imperfection n’est pas forcément un dommage réparable.","o":[["Oui, raisonnablement pour restaurer le green","Oui. Les dommages peuvent être réparés."],["Non, jamais avant le putt","Non. La réparation est autorisée."],["Oui, en modifiant librement la pente","Non. Il faut restaurer, pas améliorer au-delà de l’état initial."]]},{"v":2,"p":"Noé veut creuser un sillon vers le trou en parlant de réparation. Est-ce permis ?","i":"Marque d’impact sur le green réparée avec un relève-pitch. Noé veut creuser un sillon vers le trou en parlant de réparation. Est-ce permis ?","x":"Les dommages au green, dont les marques d’impact, peuvent être réparés raisonnablement pour retrouver autant que possible leur état initial, sans retarder déraisonnablement le jeu. Une usure naturelle ou simple imperfection n’est pas forcément un dommage réparable.","o":[["Non, il faut restaurer sans créer un sillon","Oui. Une réparation ne peut pas améliorer le green au-delà de son état initial."],["Oui, tout creusement est une réparation","Non. Un sillon créé vers le trou est une amélioration."],["Oui, si la balle est marquée","Non. Marquer la balle ne permet pas de modifier la pente."]]}]},
  {"n":46,"r":"Règle 13.1d(1)","s":"Sur le green, le putter de Tom effleure sa balle immobile et la déplace légèrement sans intention.","e":"Si le joueur déplace accidentellement sa balle ou son marque-balle sur le green, il n’y a pas de pénalité; la balle ou le marque-balle est replacé à sa position d’origine.","a":"Je replace à l’emplacement initial sans ajouter de coup.","m":"Jouer de la nouvelle place ou appliquer la règle générale du fairway.","c":"Déplacez volontairement une balle lors d’une démonstration et faites pratiquer le replacement, en rappelant le critère accidentel.","v":"Putter touchant par accident une balle immobile sur le green.","q":[{"v":0,"p":"Un putter déplace accidentellement une balle immobile sur le green. Que faire ?","i":"Putter touchant par accident une balle immobile sur le green. Un putter déplace accidentellement une balle immobile sur le green. Que faire ?","x":"Si le joueur déplace accidentellement sa balle ou son marque-balle sur le green, il n’y a pas de pénalité; la balle ou le marque-balle est replacé à sa position d’origine.","o":[["Replacer sans pénalité","Oui. C’est l’exception du green pour un déplacement accidentel."],["Jouer de la nouvelle place","Non. Elle doit être replacée."],["Ajouter automatiquement un coup","Non. Il n’y a pas de pénalité ici."]]},{"v":1,"p":"Une chaussure effleure par mégarde la balle de Mia sur le green. Quelle suite ?","i":"Putter touchant par accident une balle immobile sur le green. Une chaussure effleure par mégarde la balle de Mia sur le green. Quelle suite ?","x":"Si le joueur déplace accidentellement sa balle ou son marque-balle sur le green, il n’y a pas de pénalité; la balle ou le marque-balle est replacé à sa position d’origine.","o":[["Replacer sans pénalité","Oui. C’est l’exception du green pour un déplacement accidentel."],["Jouer de la nouvelle place","Non. Elle doit être replacée."],["Ajouter automatiquement un coup","Non. Il n’y a pas de pénalité ici."]]},{"v":2,"p":"Le marque-balle de Sara glisse accidentellement sur le green. Que doit-elle faire ?","i":"Putter touchant par accident une balle immobile sur le green. Le marque-balle de Sara glisse accidentellement sur le green. Que doit-elle faire ?","x":"Si le joueur déplace accidentellement sa balle ou son marque-balle sur le green, il n’y a pas de pénalité; la balle ou le marque-balle est replacé à sa position d’origine.","o":[["Replacer sans pénalité","Oui. C’est l’exception du green pour un déplacement accidentel."],["Jouer de la nouvelle place","Non. Elle doit être replacée."],["Ajouter automatiquement un coup","Non. Il n’y a pas de pénalité ici."]]}]},
  {"n":47,"r":"Règle 13.1d(2)","s":"Après avoir marqué, relevé et replacé sa balle sur le green, Hugo voit le vent la pousser plus près du trou.","e":"Une balle déjà relevée et replacée sur le green est replacée de nouveau à son point initial si des forces naturelles la déplacent, sans pénalité. Si elle n’avait jamais été relevée et replacée, la règle générale du vent serait différente.","a":"Je vérifie qu’elle avait été replacée et je la replace à nouveau.","m":"Jouer au nouvel endroit en oubliant qu’elle avait été replacée.","c":"Montrez le même vent avant et après un replacement sur le green.","v":"Balle replacée sur le green puis déplacée par une rafale.","q":[{"v":0,"p":"Le vent déplace une balle déjà relevée et replacée sur le green. Que faire ?","i":"Balle replacée sur le green puis déplacée par une rafale. Le vent déplace une balle déjà relevée et replacée sur le green. Que faire ?","x":"Une balle déjà relevée et replacée sur le green est replacée de nouveau à son point initial si des forces naturelles la déplacent, sans pénalité. Si elle n’avait jamais été relevée et replacée, la règle générale du vent serait différente.","o":[["La replacer au point initial sans pénalité","Oui. L’exception s’applique après un replacement sur le green."],["Jouer toujours de la nouvelle place","Non. Ce cas relève de l’exception du green."],["Ajouter deux coups","Non. Le vent ne crée pas de pénalité."]]},{"v":1,"p":"Mia a nettoyé puis replacé sa balle sur le green; une rafale la déplace. Où joue-t-elle ?","i":"Balle replacée sur le green puis déplacée par une rafale. Mia a nettoyé puis replacé sa balle sur le green; une rafale la déplace. Où joue-t-elle ?","x":"Une balle déjà relevée et replacée sur le green est replacée de nouveau à son point initial si des forces naturelles la déplacent, sans pénalité. Si elle n’avait jamais été relevée et replacée, la règle générale du vent serait différente.","o":[["La replacer au point initial sans pénalité","Oui. L’exception s’applique après un replacement sur le green."],["Jouer toujours de la nouvelle place","Non. Ce cas relève de l’exception du green."],["Ajouter deux coups","Non. Le vent ne crée pas de pénalité."]]},{"v":2,"p":"Une balle marquée, relevée et replacée sur le green roule sous le vent. Quel point reste le bon ?","i":"Balle replacée sur le green puis déplacée par une rafale. Une balle marquée, relevée et replacée sur le green roule sous le vent. Quel point reste le bon ?","x":"Une balle déjà relevée et replacée sur le green est replacée de nouveau à son point initial si des forces naturelles la déplacent, sans pénalité. Si elle n’avait jamais été relevée et replacée, la règle générale du vent serait différente.","o":[["La replacer au point initial sans pénalité","Oui. L’exception s’applique après un replacement sur le green."],["Jouer toujours de la nouvelle place","Non. Ce cas relève de l’exception du green."],["Ajouter deux coups","Non. Le vent ne crée pas de pénalité."]]}]},
  {"n":48,"r":"Règle 13.2a(2)","s":"Le putt de Sami heurte le drapeau qu’il avait laissé dans le trou avant de jouer.","e":"Une balle jouée du green qui heurte accidentellement le drapeau laissé dans le trou ne reçoit pas de pénalité; elle se joue normalement où elle repose. Le joueur peut choisir de laisser le drapeau en place avant le coup.","a":"Je décide avant le coup de laisser ou retirer le drapeau et joue la balle selon son résultat.","m":"Croire que toucher le drapeau entraîne automatiquement deux coups.","c":"Faites deux putts avec et sans drapeau, puis discutez de la règle sans imposer de stratégie.","v":"Balle puttée heurtant le drapeau resté dans le trou.","q":[{"v":0,"p":"Un putt touche le drapeau laissé dans le trou. Quelle conséquence normale ?","i":"Balle puttée heurtant le drapeau resté dans le trou. Un putt touche le drapeau laissé dans le trou. Quelle conséquence normale ?","x":"Une balle jouée du green qui heurte accidentellement le drapeau laissé dans le trou ne reçoit pas de pénalité; elle se joue normalement où elle repose. Le joueur peut choisir de laisser le drapeau en place avant le coup.","o":[["Pas de pénalité pour ce contact accidentel","Oui. Le drapeau peut rester en place."],["Deux coups obligatoires","Non. Cette pénalité automatique n’existe pas."],["Le coup est automatiquement annulé","Non. Le coup compte normalement."]]},{"v":1,"p":"Le drapeau est resté en place et la balle de Léa le frappe accidentellement. Que fait-elle ?","i":"Balle puttée heurtant le drapeau resté dans le trou. Le drapeau est resté en place et la balle de Léa le frappe accidentellement. Que fait-elle ?","x":"Une balle jouée du green qui heurte accidentellement le drapeau laissé dans le trou ne reçoit pas de pénalité; elle se joue normalement où elle repose. Le joueur peut choisir de laisser le drapeau en place avant le coup.","o":[["Pas de pénalité pour ce contact accidentel","Oui. Le drapeau peut rester en place."],["Deux coups obligatoires","Non. Cette pénalité automatique n’existe pas."],["Le coup est automatiquement annulé","Non. Le coup compte normalement."]]},{"v":2,"p":"Peut-on choisir de laisser le drapeau dans le trou avant son putt ?","i":"Balle puttée heurtant le drapeau resté dans le trou. Peut-on choisir de laisser le drapeau dans le trou avant son putt ?","x":"Une balle jouée du green qui heurte accidentellement le drapeau laissé dans le trou ne reçoit pas de pénalité; elle se joue normalement où elle repose. Le joueur peut choisir de laisser le drapeau en place avant le coup.","o":[["Oui, le drapeau peut rester en place","Oui. Le joueur peut choisir cette option avant son coup."],["Non, il doit toujours être retiré","Non. Ce n’est pas obligatoire."],["Oui, mais deux coups si la balle le touche","Non. Un contact accidentel n’entraîne pas cette pénalité."]]}]}
  ,
  {"n":49,"r":"Règle 19.1","s":"La balle de Nora est derrière un arbre; son coach pense qu’elle est injouable.","e":"Seul le joueur peut décider de prendre le dégagement pour balle injouable. Il est possible partout sur le parcours sauf en zone à pénalité, où la Règle 17 s’applique.","a":"Je décide moi-même si je prends une option injouable avec sa pénalité.","m":"Laisser le coach déclarer officiellement la balle injouable à ma place.","c":"Faites proposer des options, puis laissez le junior décider et expliquer pourquoi.","v":"Joueuse examinant sa balle derrière un tronc, coach observant.","q":[{"v":0,"p":"Qui peut décider de prendre un dégagement pour balle injouable ?","i":"Joueuse examinant sa balle derrière un tronc, coach observant. Qui peut décider de prendre un dégagement pour balle injouable ?","x":"Seul le joueur peut décider de prendre le dégagement pour balle injouable. Il est possible partout sur le parcours sauf en zone à pénalité, où la Règle 17 s’applique.","o":[["Le joueur lui-même, hors zone à pénalité","Oui. La décision lui appartient et la zone limite l’option."],["N’importe quel spectateur","Non. Le spectateur ne prend pas cette décision."],["Le coach à la place du joueur","Non. Il peut aider à comprendre, pas décider."]]},{"v":1,"p":"Le coach de Max peut-il imposer qu’il déclare sa balle injouable ?","i":"Joueuse examinant sa balle derrière un tronc, coach observant. Le coach de Max peut-il imposer qu’il déclare sa balle injouable ?","x":"Seul le joueur peut décider de prendre le dégagement pour balle injouable. Il est possible partout sur le parcours sauf en zone à pénalité, où la Règle 17 s’applique.","o":[["Non, seul le joueur décide","Oui. Le coach peut expliquer mais pas imposer la décision."],["Oui, tout coach peut l’imposer","Non. La décision appartient au joueur."],["Oui, si la balle est derrière un arbre","Non. Le lie ne transfère pas la décision."]]},{"v":2,"p":"La balle de Mia est dans une zone à pénalité. Peut-elle invoquer la Règle 19 ?","i":"Joueuse examinant sa balle derrière un tronc, coach observant. La balle de Mia est dans une zone à pénalité. Peut-elle invoquer la Règle 19 ?","x":"Seul le joueur peut décider de prendre le dégagement pour balle injouable. Il est possible partout sur le parcours sauf en zone à pénalité, où la Règle 17 s’applique.","o":[["Non, la Règle 17 s’applique en zone à pénalité","Oui. La Règle 19 n’y donne pas l’option injouable."],["Oui, toute balle difficile relève de la Règle 19","Non. La zone à pénalité est exclue."],["Oui, gratuitement","Non. Le dégagement de cette zone est normalement pénalisé."]]}]},
  {"n":50,"r":"Règles 19.2a, 18.1 et 14.6","s":"Sous des branches, Léo préfère revenir jouer d’où il avait effectué son coup précédent.","e":"Coup et distance est une option de balle injouable pour un coup de pénalité : le joueur rejoue de l’endroit du coup précédent, selon la procédure propre à cette zone.","a":"Je compte un coup de pénalité et retourne à l’endroit du coup précédent.","m":"Confondre l’endroit du coup précédent et celui où repose la balle injouable.","c":"Placez deux repères et faites compter le coup initial, la pénalité et le coup suivant.","v":"Balle sous des branches, flèche ramenant au point du coup précédent.","q":[{"v":0,"p":"Avec coup et distance pour une balle injouable, d’où rejoue-t-on ?","i":"Balle sous des branches, flèche ramenant au point du coup précédent. Avec coup et distance pour une balle injouable, d’où rejoue-t-on ?","x":"Coup et distance est une option de balle injouable pour un coup de pénalité : le joueur rejoue de l’endroit du coup précédent, selon la procédure propre à cette zone.","o":[["De l’endroit du coup précédent avec un coup de pénalité","Oui. C’est l’option de coup et distance."],["Au point de la balle injouable sans pénalité","Non. Il faut revenir au coup précédent."],["N’importe où à deux longueurs de club","Non. C’est une autre option avec une référence différente."]]},{"v":1,"p":"Mia choisit coup et distance après un coup du départ. Où peut-elle rejouer ?","i":"Balle sous des branches, flèche ramenant au point du coup précédent. Mia choisit coup et distance après un coup du départ. Où peut-elle rejouer ?","x":"Coup et distance est une option de balle injouable pour un coup de pénalité : le joueur rejoue de l’endroit du coup précédent, selon la procédure propre à cette zone.","o":[["De l’endroit du coup précédent avec un coup de pénalité","Oui. C’est l’option de coup et distance."],["Au point de la balle injouable sans pénalité","Non. Il faut revenir au coup précédent."],["N’importe où à deux longueurs de club","Non. C’est une autre option avec une référence différente."]]},{"v":2,"p":"Une balle injouable est près du green. Le point de coup et distance est-il l’endroit où elle repose ?","i":"Balle sous des branches, flèche ramenant au point du coup précédent. Une balle injouable est près du green. Le point de coup et distance est-il l’endroit où elle repose ?","x":"Coup et distance est une option de balle injouable pour un coup de pénalité : le joueur rejoue de l’endroit du coup précédent, selon la procédure propre à cette zone.","o":[["Non, c’est l’endroit du coup précédent","Oui. Coup et distance revient au coup antérieur."],["Oui, c’est la balle injouable","Non. Ce serait un autre point de référence."],["Oui, n’importe où près du green","Non. Le joueur ne choisit pas librement."]]}]},
  {"n":51,"r":"Règle 19.2b ; Règle 14.3b(3)","s":"La balle de Zoé est derrière un buisson dans la zone générale; elle choisit de reculer sur la ligne.","e":"Pour un coup de pénalité, le dégagement en arrière sur la ligne utilise une ligne imaginaire partant du trou, passant par la position de la balle et se prolongeant vers l’arrière. La balle est droppée sur la ligne; le point de contact crée la zone de dégagement.","a":"Je trace la ligne trou-balle et je recule sur son prolongement avant de dropper.","m":"Reculer simplement vers le départ sans respecter la ligne.","c":"Tracez une ficelle du drapeau par la balle puis prolongez-la.","v":"Ligne droite du trou par une balle derrière un buisson vers l’arrière.","q":[{"v":0,"p":"Quel alignement définit le recul sur la ligne pour une balle injouable ?","i":"Ligne droite du trou par une balle derrière un buisson vers l’arrière. Quel alignement définit le recul sur la ligne pour une balle injouable ?","x":"Pour un coup de pénalité, le dégagement en arrière sur la ligne utilise une ligne imaginaire partant du trou, passant par la position de la balle et se prolongeant vers l’arrière. La balle est droppée sur la ligne; le point de contact crée la zone de dégagement.","o":[["Trou, balle, puis prolongement arrière","Oui. Cette ligne fixe le drop autorisé."],["Balle vers le départ sans autre repère","Non. Le trou fait partie de la ligne."],["N’importe quelle direction favorable","Non. La direction est définie."]]},{"v":1,"p":"Léa veut reculer sur la ligne derrière sa balle. Par quels points passe cette ligne ?","i":"Ligne droite du trou par une balle derrière un buisson vers l’arrière. Léa veut reculer sur la ligne derrière sa balle. Par quels points passe cette ligne ?","x":"Pour un coup de pénalité, le dégagement en arrière sur la ligne utilise une ligne imaginaire partant du trou, passant par la position de la balle et se prolongeant vers l’arrière. La balle est droppée sur la ligne; le point de contact crée la zone de dégagement.","o":[["Trou, balle, puis prolongement arrière","Oui. Cette ligne fixe le drop autorisé."],["Balle vers le départ sans autre repère","Non. Le trou fait partie de la ligne."],["N’importe quelle direction favorable","Non. La direction est définie."]]},{"v":2,"p":"Max droppe loin à gauche de la ligne trou-balle sans autre option. Est-ce le recul sur la ligne ?","i":"Ligne droite du trou par une balle derrière un buisson vers l’arrière. Max droppe loin à gauche de la ligne trou-balle sans autre option. Est-ce le recul sur la ligne ?","x":"Pour un coup de pénalité, le dégagement en arrière sur la ligne utilise une ligne imaginaire partant du trou, passant par la position de la balle et se prolongeant vers l’arrière. La balle est droppée sur la ligne; le point de contact crée la zone de dégagement.","o":[["Non, la balle doit être droppée sur la ligne autorisée","Oui. La ligne passe par le trou et la position initiale."],["Oui, tout point à gauche convient","Non. Ce n’est pas le recul sur la ligne."],["Oui, si la balle reste dans la zone générale","Non. La zone seule ne remplace pas la ligne."]]}]},
  {"n":52,"r":"Règle 19.2c","s":"La balle de Yanis est sous une haie dans la zone générale; il choisit le dégagement latéral.","e":"Pour un coup de pénalité, la zone latérale d’une balle injouable s’étend à deux longueurs de club de l’emplacement de la balle, sans se rapprocher du trou.","a":"Je prends l’emplacement de la balle comme référence et mesure deux longueurs de club.","m":"Mesurer depuis le bord de la haie ou du dernier coup.","c":"Dessinez une zone latérale de deux clubs et excluez les points plus près du trou.","v":"Balle sous une haie et zone de deux longueurs de club sur le côté.","q":[{"v":0,"p":"D’où mesure-t-on deux longueurs de club pour une balle injouable latérale ?","i":"Balle sous une haie et zone de deux longueurs de club sur le côté. D’où mesure-t-on deux longueurs de club pour une balle injouable latérale ?","x":"Pour un coup de pénalité, la zone latérale d’une balle injouable s’étend à deux longueurs de club de l’emplacement de la balle, sans se rapprocher du trou.","o":[["De l’emplacement de la balle, sans se rapprocher","Oui. C’est le point de référence et la limite."],["Du bord de l’obstacle le plus proche","Non. La balle, pas l’obstacle, sert de référence."],["Du point du coup précédent uniquement","Non. Ce serait une autre option."]]},{"v":1,"p":"Une balle est sous un arbre. Quel point sert de référence au dégagement latéral ?","i":"Balle sous une haie et zone de deux longueurs de club sur le côté. Une balle est sous un arbre. Quel point sert de référence au dégagement latéral ?","x":"Pour un coup de pénalité, la zone latérale d’une balle injouable s’étend à deux longueurs de club de l’emplacement de la balle, sans se rapprocher du trou.","o":[["De l’emplacement de la balle, sans se rapprocher","Oui. C’est le point de référence et la limite."],["Du bord de l’obstacle le plus proche","Non. La balle, pas l’obstacle, sert de référence."],["Du point du coup précédent uniquement","Non. Ce serait une autre option."]]},{"v":2,"p":"Peut-on dropper plus près du trou sous prétexte de rester à deux clubs ?","i":"Balle sous une haie et zone de deux longueurs de club sur le côté. Peut-on dropper plus près du trou sous prétexte de rester à deux clubs ?","x":"Pour un coup de pénalité, la zone latérale d’une balle injouable s’étend à deux longueurs de club de l’emplacement de la balle, sans se rapprocher du trou.","o":[["Non, le drop ne doit pas se rapprocher du trou","Oui. C’est une limite de la zone latérale."],["Oui, deux clubs suffisent toujours","Non. La distance au trou compte aussi."],["Oui, si le lie est meilleur","Non. La qualité du lie n’annule pas la limite."]]}]},
  {"n":53,"r":"Règle 14.3b(1)-(3)","s":"Ana doit dropper sa balle et la lâche depuis la hauteur de sa taille.","e":"Le joueur lui-même lâche la balle verticalement depuis la hauteur de son genou en position debout, sans lui donner d’effet ni toucher son corps ou son matériel avant le sol, dans la zone ou sur la ligne requise.","a":"Je positionne la balle à hauteur de genou, la lâche droit vers le bas et vérifie le premier contact.","m":"Dropper depuis l’épaule ou jeter la balle vers la meilleure position.","c":"Faites pratiquer plusieurs drops devant un miroir sans réellement jouer.","v":"Joueuse lâchant verticalement une balle à hauteur de son genou.","q":[{"v":0,"p":"De quelle hauteur la balle doit-elle être lâchée pour un drop ?","i":"Joueuse lâchant verticalement une balle à hauteur de son genou. De quelle hauteur la balle doit-elle être lâchée pour un drop ?","x":"Le joueur lui-même lâche la balle verticalement depuis la hauteur de son genou en position debout, sans lui donner d’effet ni toucher son corps ou son matériel avant le sol, dans la zone ou sur la ligne requise.","o":[["De la hauteur du genou du joueur","Oui. La balle doit tomber verticalement de cette hauteur."],["De l’épaule","Non. Cette hauteur n’est plus la procédure."],["De la taille","Non. C’est trop haut pour un drop réglementaire."]]},{"v":1,"p":"Mia lâche depuis sa taille. Est-ce la hauteur correcte ?","i":"Joueuse lâchant verticalement une balle à hauteur de son genou. Mia lâche depuis sa taille. Est-ce la hauteur correcte ?","x":"Le joueur lui-même lâche la balle verticalement depuis la hauteur de son genou en position debout, sans lui donner d’effet ni toucher son corps ou son matériel avant le sol, dans la zone ou sur la ligne requise.","o":[["Non, il faut la hauteur du genou","Oui. La taille est trop haute."],["Oui, la taille est la hauteur réglementaire","Non. La règle précise le genou."],["Oui, seulement sur le green","Non. Le lieu ne change pas la hauteur."]]},{"v":2,"p":"Qui doit normalement lâcher la balle lors d’un drop ?","i":"Joueuse lâchant verticalement une balle à hauteur de son genou. Qui doit normalement lâcher la balle lors d’un drop ?","x":"Le joueur lui-même lâche la balle verticalement depuis la hauteur de son genou en position debout, sans lui donner d’effet ni toucher son corps ou son matériel avant le sol, dans la zone ou sur la ligne requise.","o":[["Le joueur lui-même","Oui. Hors modifications particulières, lui seul effectue le drop."],["Le cadet à sa place","Non. Le cadet ne peut normalement pas dropper."],["N’importe quel partenaire","Non. Le drop revient au joueur."]]}]},
  {"n":54,"r":"Règle 14.3c","s":"La balle de Noé est droppée correctement, touche la zone de dégagement puis roule hors de cette zone.","e":"Si une balle droppée correctement s’arrête hors de la zone, on droppe une seconde fois. Si elle ressort encore, on la place au point où elle a touché le sol lors du second drop; si elle ne tient pas, la procédure prévoit un point le plus proche où elle reste au repos.","a":"Je vérifie où la balle s’arrête, recommence une fois si elle sort, puis place selon la règle.","m":"Jouer une balle sortie de la zone ou multiplier indéfiniment les drops.","c":"Délimitez une zone et faites rouler une balle deux fois pour pratiquer la mise en place.","v":"Balle roulant hors d’une zone de dégagement marquée par une corde.","q":[{"v":0,"p":"Après un premier drop correct, la balle s’arrête hors de la zone. Que fais-tu ?","i":"Balle roulant hors d’une zone de dégagement marquée par une corde. Après un premier drop correct, la balle s’arrête hors de la zone. Que fais-tu ?","x":"Si une balle droppée correctement s’arrête hors de la zone, on droppe une seconde fois. Si elle ressort encore, on la place au point où elle a touché le sol lors du second drop; si elle ne tient pas, la procédure prévoit un point le plus proche où elle reste au repos.","o":[["Redropper, puis placer si le second sort aussi","Oui. La Règle 14.3c fixe cette séquence."],["Jouer où la balle roule","Non. Elle doit rester dans la zone."],["Ajouter automatiquement deux coups","Non. Corriger selon la procédure n’ajoute pas cette pénalité."]]},{"v":1,"p":"Après un deuxième drop correct, la balle ressort encore. Quelle suite ?","i":"Balle roulant hors d’une zone de dégagement marquée par une corde. Après un deuxième drop correct, la balle ressort encore. Quelle suite ?","x":"Si une balle droppée correctement s’arrête hors de la zone, on droppe une seconde fois. Si elle ressort encore, on la place au point où elle a touché le sol lors du second drop; si elle ne tient pas, la procédure prévoit un point le plus proche où elle reste au repos.","o":[["Placer au point de contact du second drop","Oui. Après deux sorties correctes, on passe au placement."],["Dropper une troisième fois","Non. La séquence normale s’arrête à deux drops."],["Jouer hors de la zone","Non. La balle doit être mise en jeu selon la procédure."]]},{"v":2,"p":"Une balle est droppée correctement mais roule hors de la zone. Peut-on la jouer là ?","i":"Balle roulant hors d’une zone de dégagement marquée par une corde. Une balle est droppée correctement mais roule hors de la zone. Peut-on la jouer là ?","x":"Si une balle droppée correctement s’arrête hors de la zone, on droppe une seconde fois. Si elle ressort encore, on la place au point où elle a touché le sol lors du second drop; si elle ne tient pas, la procédure prévoit un point le plus proche où elle reste au repos.","o":[["Non, il faut la redropper","Oui. Elle doit s’arrêter dans la zone."],["Oui, car elle a touché la zone","Non. Le point d’arrêt compte aussi."],["Oui, avec un coup de pénalité","Non. Il faut corriger la procédure."]]}]}
  ,
  {"n":55,"r":"Règle 4.1b(1) ; Règle 4.1c","s":"Sami découvre un quinzième club dans son sac au troisième trou.","e":"Quatorze clubs au plus sont autorisés. Dès qu’un excédent est découvert, le joueur doit clairement mettre un club hors jeu et appliquer la pénalité dépendant de la forme de jeu et du moment de découverte.","a":"Je déclare immédiatement le club excédentaire hors jeu à un autre joueur ou mon marqueur, puis vérifie la pénalité.","m":"Simplement promettre de ne pas l’utiliser sans mise hors jeu claire.","c":"Faites compter des sacs de 13, 14 et 15 clubs et formuler la déclaration.","v":"Sac de golf contenant un club en trop montré à un marqueur.","q":[{"v":0,"p":"Que faire dès la découverte d’un quinzième club pendant le tour ?","i":"Sac de golf contenant un club en trop montré à un marqueur. Que faire dès la découverte d’un quinzième club pendant le tour ?","x":"Quatorze clubs au plus sont autorisés. Dès qu’un excédent est découvert, le joueur doit clairement mettre un club hors jeu et appliquer la pénalité dépendant de la forme de jeu et du moment de découverte.","o":[["Mettre clairement le club excédentaire hors jeu","Oui. L’action doit être explicite dès la découverte."],["Le garder disponible sans rien dire","Non. La mise hors jeu est exigée."],["Attendre la fin du tour","Non. La correction est immédiate."]]},{"v":1,"p":"Léa compte quinze clubs avant de continuer le troisième trou. Quelle action immédiate ?","i":"Sac de golf contenant un club en trop montré à un marqueur. Léa compte quinze clubs avant de continuer le troisième trou. Quelle action immédiate ?","x":"Quatorze clubs au plus sont autorisés. Dès qu’un excédent est découvert, le joueur doit clairement mettre un club hors jeu et appliquer la pénalité dépendant de la forme de jeu et du moment de découverte.","o":[["Mettre clairement le club excédentaire hors jeu","Oui. L’action doit être explicite dès la découverte."],["Le garder disponible sans rien dire","Non. La mise hors jeu est exigée."],["Attendre la fin du tour","Non. La correction est immédiate."]]},{"v":2,"p":"Max n’utilise pas son quinzième club mais ne le déclare pas hors jeu. Est-ce suffisant ?","i":"Sac de golf contenant un club en trop montré à un marqueur. Max n’utilise pas son quinzième club mais ne le déclare pas hors jeu. Est-ce suffisant ?","x":"Quatorze clubs au plus sont autorisés. Dès qu’un excédent est découvert, le joueur doit clairement mettre un club hors jeu et appliquer la pénalité dépendant de la forme de jeu et du moment de découverte.","o":[["Non, il doit le mettre clairement hors jeu","Oui. Ne pas l’utiliser ne suffit pas."],["Oui, le silence suffit","Non. Il faut une mise hors jeu claire."],["Oui, s’il ne l’a pas encore sorti du sac","Non. Il compte dans la limite."]]}]},
  {"n":56,"r":"Règle 4.1a(2) ; éventuelle Règle locale type G-9","s":"Le fer de Mia se casse lors d’un coup normal, sans geste de colère.","e":"Un club conforme endommagé pendant le tour peut être utilisé ou réparé; hors abus, il peut normalement être remplacé sous les restrictions de la règle. Une règle locale G-9 peut restreindre le remplacement; elle doit être vérifiée.","a":"Je vérifie la cause du dommage et la règle locale, puis retire l’ancien club du jeu avant de jouer avec un remplaçant autorisé.","m":"Croire que tout club rayé doit être remplacé ou que l’abus donne toujours le droit de remplacer.","c":"Comparez casse normale, petite rayure et dommage causé par colère.","v":"Fer cassé pendant un coup normal, joueur vérifiant la tête du club.","q":[{"v":0,"p":"Un club se casse lors d’un coup normal. Quelle vérification avant remplacement ?","i":"Fer cassé pendant un coup normal, joueur vérifiant la tête du club. Un club se casse lors d’un coup normal. Quelle vérification avant remplacement ?","x":"Un club conforme endommagé pendant le tour peut être utilisé ou réparé; hors abus, il peut normalement être remplacé sous les restrictions de la règle. Une règle locale G-9 peut restreindre le remplacement; elle doit être vérifiée.","o":[["Vérifier la règle 4.1a et toute règle locale applicable","Oui. Le remplacement peut être permis mais aussi limité."],["Le remplacer toujours, même après abus","Non. L’abus exclut le remplacement ordinaire."],["Emprunter librement le club d’un autre joueur","Non. Le remplacement suit aussi les restrictions sur l’ajout de clubs."]]},{"v":1,"p":"Léa veut remplacer un club endommagé sans abus. Que doit-elle consulter ?","i":"Fer cassé pendant un coup normal, joueur vérifiant la tête du club. Léa veut remplacer un club endommagé sans abus. Que doit-elle consulter ?","x":"Un club conforme endommagé pendant le tour peut être utilisé ou réparé; hors abus, il peut normalement être remplacé sous les restrictions de la règle. Une règle locale G-9 peut restreindre le remplacement; elle doit être vérifiée.","o":[["Vérifier la règle 4.1a et toute règle locale applicable","Oui. Le remplacement peut être permis mais aussi limité."],["Le remplacer toujours, même après abus","Non. L’abus exclut le remplacement ordinaire."],["Emprunter librement le club d’un autre joueur","Non. Le remplacement suit aussi les restrictions sur l’ajout de clubs."]]},{"v":2,"p":"Un club est rayé mais jouable et une règle locale G-9 s’applique. Peut-on supposer un remplacement automatique ?","i":"Fer cassé pendant un coup normal, joueur vérifiant la tête du club. Un club est rayé mais jouable et une règle locale G-9 s’applique. Peut-on supposer un remplacement automatique ?","x":"Un club conforme endommagé pendant le tour peut être utilisé ou réparé; hors abus, il peut normalement être remplacé sous les restrictions de la règle. Une règle locale G-9 peut restreindre le remplacement; elle doit être vérifiée.","o":[["Non, la règle locale G-9 peut restreindre le remplacement","Oui. Une simple rayure ne suffit pas nécessairement."],["Oui, toute rayure autorise automatiquement un nouveau club","Non. Il faut examiner dommage et règle locale."],["Oui, même en cas d’abus","Non. L’abus exclut le remplacement ordinaire."]]}]},
  {"n":57,"r":"Règle 4.3a(1)","s":"Noé utilise une montre qui affiche la distance jusqu’au green.","e":"La mesure de distance seule est généralement autorisée, sauf règle locale l’interdisant. Les fonctions qui calculent une distance ajustée par pente ou recommandent un club ne sont pas autorisées pendant le tour.","a":"J’utilise la distance simple et désactive les fonctions interdites; je consulte la règle locale.","m":"Confondre la distance réelle et une distance « joue comme » corrigée par la pente.","c":"Montrez deux affichages fictifs : distance brute et distance ajustée.","v":"Montre affichant une distance brute vers le green, pente visible en arrière-plan.","q":[{"v":0,"p":"Quelle mesure un appareil peut-il généralement fournir pendant le tour ?","i":"Montre affichant une distance brute vers le green, pente visible en arrière-plan. Quelle mesure un appareil peut-il généralement fournir pendant le tour ?","x":"La mesure de distance seule est généralement autorisée, sauf règle locale l’interdisant. Les fonctions qui calculent une distance ajustée par pente ou recommandent un club ne sont pas autorisées pendant le tour.","o":[["La distance seule, sous réserve d’une règle locale","Oui. Les calculs d’aide au jeu sont différents."],["Une recommandation automatique de club","Non. Elle constitue une aide interdite."],["Une distance ajustée par la pente","Non. L’ajustement n’est pas une simple mesure."]]},{"v":1,"p":"La montre de Mia affiche la distance brute au drapeau. Quelle vérification ?","i":"Montre affichant une distance brute vers le green, pente visible en arrière-plan. La montre de Mia affiche la distance brute au drapeau. Quelle vérification ?","x":"La mesure de distance seule est généralement autorisée, sauf règle locale l’interdisant. Les fonctions qui calculent une distance ajustée par pente ou recommandent un club ne sont pas autorisées pendant le tour.","o":[["La distance seule, sous réserve d’une règle locale","Oui. Les calculs d’aide au jeu sont différents."],["Une recommandation automatique de club","Non. Elle constitue une aide interdite."],["Une distance ajustée par la pente","Non. L’ajustement n’est pas une simple mesure."]]},{"v":2,"p":"Un appareil propose un club en fonction du vent et de la pente. Peut-on utiliser cette aide ?","i":"Montre affichant une distance brute vers le green, pente visible en arrière-plan. Un appareil propose un club en fonction du vent et de la pente. Peut-on utiliser cette aide ?","x":"La mesure de distance seule est généralement autorisée, sauf règle locale l’interdisant. Les fonctions qui calculent une distance ajustée par pente ou recommandent un club ne sont pas autorisées pendant le tour.","o":[["Non, la recommandation de club est une aide interdite","Oui. Une simple distance est différente d’un conseil calculé."],["Oui, toute fonction d’une montre est permise","Non. Les fonctions d’aide sont restreintes."],["Oui, si la distance brute est aussi affichée","Non. Cela ne rend pas la recommandation permise."]]}]},
  {"n":58,"r":"Règle 10.2a ; définition « Conseil »","s":"En compétition individuelle, Zoé demande à une concurrente quel club utiliser pour franchir un obstacle.","e":"Demander ou donner un conseil sur le choix d’un club ou la façon de jouer à un autre joueur de la compétition sur le parcours est interdit pendant le tour, sauf personnes autorisées comme son propre cadet ou partenaire dans certaines formes.","a":"Je prends ma décision moi-même ou consulte seulement une personne autorisée.","m":"Croire qu’un conseil est permis dès lors que l’autre joueur est amical.","c":"Classez différentes phrases : distance publique, règle de golf, choix de club.","v":"Deux joueuses sur le fairway discutant d’un choix de club.","q":[{"v":0,"p":"Peux-tu demander à une concurrente quel club choisir pendant ton tour individuel ?","i":"Deux joueuses sur le fairway discutant d’un choix de club. Peux-tu demander à une concurrente quel club choisir pendant ton tour individuel ?","x":"Demander ou donner un conseil sur le choix d’un club ou la façon de jouer à un autre joueur de la compétition sur le parcours est interdit pendant le tour, sauf personnes autorisées comme son propre cadet ou partenaire dans certaines formes.","o":[["Non pour un choix de club à un autre compétiteur","Oui. Le choix de club est un conseil."],["Oui, si la personne est sympathique","Non. L’amitié ne change pas la règle."],["Oui, si la réponse est discrète","Non. La discrétion ne rend pas le conseil permis."]]},{"v":1,"p":"Léa demande à un autre compétiteur comment jouer son prochain coup. Est-ce un conseil autorisé ?","i":"Deux joueuses sur le fairway discutant d’un choix de club. Léa demande à un autre compétiteur comment jouer son prochain coup. Est-ce un conseil autorisé ?","x":"Demander ou donner un conseil sur le choix d’un club ou la façon de jouer à un autre joueur de la compétition sur le parcours est interdit pendant le tour, sauf personnes autorisées comme son propre cadet ou partenaire dans certaines formes.","o":[["Non pour un choix de club à un autre compétiteur","Oui. Le choix de club est un conseil."],["Oui, si la personne est sympathique","Non. L’amitié ne change pas la règle."],["Oui, si la réponse est discrète","Non. La discrétion ne rend pas le conseil permis."]]},{"v":2,"p":"Noé demande la distance jusqu’au drapeau, information publique. Est-ce automatiquement un conseil interdit ?","i":"Deux joueuses sur le fairway discutant d’un choix de club. Noé demande la distance jusqu’au drapeau, information publique. Est-ce automatiquement un conseil interdit ?","x":"Demander ou donner un conseil sur le choix d’un club ou la façon de jouer à un autre joueur de la compétition sur le parcours est interdit pendant le tour, sauf personnes autorisées comme son propre cadet ou partenaire dans certaines formes.","o":[["Non, une distance publique n’est pas en soi un conseil interdit","Oui. Le choix du club serait différent."],["Oui, toute information est un conseil","Non. Les faits publics peuvent être partagés."],["Oui, seulement si la distance est demandée à voix basse","Non. Le volume de voix ne définit pas le conseil."]]}]},
  {"n":59,"r":"Règle 10.2b(1)-(3)","s":"Le cadet d’Emma pointe une cible lointaine avant qu’elle prépare son coup.","e":"Une ligne de jeu peut être indiquée avant le coup selon les limites de la règle; une personne ou un objet placé pour aider à viser ne doit pas rester dans une position interdite pendant le coup. Sur le green, les restrictions sont plus précises.","a":"Je fais retirer toute aide au placement avant de jouer et je vérifie les règles propres au green.","m":"Laisser quelqu’un aligner mon coup depuis derrière la balle pendant la frappe.","c":"Faites simuler un pointage temporaire puis le retrait avant le coup.","v":"Cadet montrant une cible lointaine puis s’écartant avant le coup.","q":[{"v":0,"p":"Peut-on demander à son cadet d’indiquer une cible avant le coup ?","i":"Cadet montrant une cible lointaine puis s’écartant avant le coup. Peut-on demander à son cadet d’indiquer une cible avant le coup ?","x":"Une ligne de jeu peut être indiquée avant le coup selon les limites de la règle; une personne ou un objet placé pour aider à viser ne doit pas rester dans une position interdite pendant le coup. Sur le green, les restrictions sont plus précises.","o":[["Oui, dans les limites prévues et sans aide interdite pendant le coup","Oui. L’aide doit respecter la Règle 10.2b."],["Oui, avec une personne cible qui reste toujours","Non. Une aide placée pour viser ne peut pas rester illicitement."],["Jamais aucune indication de direction","Non. Certaines indications sont permises."]]},{"v":1,"p":"Le cadet pointe une direction puis s’écarte avant le coup du fairway. Quelle précaution ?","i":"Cadet montrant une cible lointaine puis s’écartant avant le coup. Le cadet pointe une direction puis s’écarte avant le coup du fairway. Quelle précaution ?","x":"Une ligne de jeu peut être indiquée avant le coup selon les limites de la règle; une personne ou un objet placé pour aider à viser ne doit pas rester dans une position interdite pendant le coup. Sur le green, les restrictions sont plus précises.","o":[["Oui, dans les limites prévues et sans aide interdite pendant le coup","Oui. L’aide doit respecter la Règle 10.2b."],["Oui, avec une personne cible qui reste toujours","Non. Une aide placée pour viser ne peut pas rester illicitement."],["Jamais aucune indication de direction","Non. Certaines indications sont permises."]]},{"v":2,"p":"Une personne reste placée sur la ligne pour servir de cible pendant le coup. Quelle vérification ?","i":"Cadet montrant une cible lointaine puis s’écartant avant le coup. Une personne reste placée sur la ligne pour servir de cible pendant le coup. Quelle vérification ?","x":"Une ligne de jeu peut être indiquée avant le coup selon les limites de la règle; une personne ou un objet placé pour aider à viser ne doit pas rester dans une position interdite pendant le coup. Sur le green, les restrictions sont plus précises.","o":[["Elle doit être retirée si sa présence constitue une aide interdite","Oui. Une personne ne peut pas servir illicitement de cible pendant le coup."],["Elle peut toujours rester sur la ligne","Non. La Règle 10.2b impose des restrictions."],["La couleur de ses vêtements décide","Non. Sa position et son rôle importent."]]}]},
  {"n":60,"r":"Règle 10.2b(4)","s":"Pendant que Léo prend son stance, son cadet reste derrière lui sur le prolongement de la ligne de jeu pour l’aligner.","e":"Le cadet ne doit pas se tenir délibérément dans la zone restreinte derrière la balle pendant que le joueur commence à prendre son stance pour le coup, avec des nuances et possibilités de correction selon la zone et le moment. La simple présence involontaire est différente.","a":"Je prends mon stance sans alignement interdit par mon cadet et m’assure qu’il s’écarte à temps selon la règle.","m":"Croire qu’il suffit toujours que le cadet quitte la ligne une fois le stance établi.","c":"Rejouez la séquence avant et après le début du stance, puis analysez les possibilités de correction.","v":"Cadet derrière un joueur en cours de stance, ligne de jeu matérialisée.","q":[{"v":0,"p":"Où le cadet ne doit-il pas se tenir délibérément pendant la prise de stance ?","i":"Cadet derrière un joueur en cours de stance, ligne de jeu matérialisée. Où le cadet ne doit-il pas se tenir délibérément pendant la prise de stance ?","x":"Le cadet ne doit pas se tenir délibérément dans la zone restreinte derrière la balle pendant que le joueur commence à prendre son stance pour le coup, avec des nuances et possibilités de correction selon la zone et le moment. La simple présence involontaire est différente.","o":[["Dans la zone restreinte derrière la ligne de jeu","Oui. Cette position délibérée est encadrée."],["Toujours devant le joueur","Non. Ce n’est pas la zone visée par cette restriction."],["La position du cadet est sans importance","Non. Elle peut entraîner une pénalité."]]},{"v":1,"p":"Le cadet de Mia reste derrière sa balle pour l’aligner alors qu’elle prend son stance. Que doit-elle vérifier ?","i":"Cadet derrière un joueur en cours de stance, ligne de jeu matérialisée. Le cadet de Mia reste derrière sa balle pour l’aligner alors qu’elle prend son stance. Que doit-elle vérifier ?","x":"Le cadet ne doit pas se tenir délibérément dans la zone restreinte derrière la balle pendant que le joueur commence à prendre son stance pour le coup, avec des nuances et possibilités de correction selon la zone et le moment. La simple présence involontaire est différente.","o":[["Dans la zone restreinte derrière la ligne de jeu","Oui. Cette position délibérée est encadrée."],["Toujours devant le joueur","Non. Ce n’est pas la zone visée par cette restriction."],["La position du cadet est sans importance","Non. Elle peut entraîner une pénalité."]]},{"v":2,"p":"Un cadet passe involontairement derrière le joueur sans aide au visée. Est-ce identique à un alignement délibéré ?","i":"Cadet derrière un joueur en cours de stance, ligne de jeu matérialisée. Un cadet passe involontairement derrière le joueur sans aide au visée. Est-ce identique à un alignement délibéré ?","x":"Le cadet ne doit pas se tenir délibérément dans la zone restreinte derrière la balle pendant que le joueur commence à prendre son stance pour le coup, avec des nuances et possibilités de correction selon la zone et le moment. La simple présence involontaire est différente.","o":[["Non, le caractère délibéré et l’aide visée comptent","Oui. Une présence involontaire n’est pas identique."],["Oui, toute présence derrière le joueur est identique","Non. La règle distingue l’intention."],["Oui, si le cadet est loin du green","Non. Ce n’est pas le critère décisif."]]}]}
  ,
  {"n":61,"r":"Règle 3.3b(1)-(2)","s":"Après le tour en stroke play, Ana reçoit sa carte remplie par son marqueur.","e":"Le marqueur certifie les scores des trous; le joueur doit vérifier ses scores, résoudre les doutes avec le Comité et certifier puis rendre la carte selon les modalités prévues. Le Comité additionne le total et applique les handicaps.","a":"Je contrôle chaque trou avec mon marqueur, fais corriger les doutes et rends la carte certifiée.","m":"Signer sans relire ou croire que le joueur doit lui-même calculer le total officiel.","c":"Faites comparer une carte fictive et le récit des trous avant certification.","v":"Joueuse et marqueur vérifiant ensemble une carte de score.","q":[{"v":0,"p":"Que doit vérifier le joueur avant de rendre sa carte en stroke play ?","i":"Joueuse et marqueur vérifiant ensemble une carte de score. Que doit vérifier le joueur avant de rendre sa carte en stroke play ?","x":"Le marqueur certifie les scores des trous; le joueur doit vérifier ses scores, résoudre les doutes avec le Comité et certifier puis rendre la carte selon les modalités prévues. Le Comité additionne le total et applique les handicaps.","o":[["Vérifier les scores des trous et certifier la carte","Oui. Le joueur répond de ses scores par trou."],["Ne lire que le total calculé","Non. Les scores de chaque trou doivent être vérifiés."],["Laisser le marqueur décider seul de tout doute","Non. Le Comité doit être consulté si nécessaire."]]},{"v":1,"p":"Le marqueur a inscrit les coups de Léa; quelle responsabilité lui reste-t-il ?","i":"Joueuse et marqueur vérifiant ensemble une carte de score. Le marqueur a inscrit les coups de Léa; quelle responsabilité lui reste-t-il ?","x":"Le marqueur certifie les scores des trous; le joueur doit vérifier ses scores, résoudre les doutes avec le Comité et certifier puis rendre la carte selon les modalités prévues. Le Comité additionne le total et applique les handicaps.","o":[["Vérifier les scores des trous et certifier la carte","Oui. Le joueur répond de ses scores par trou."],["Ne lire que le total calculé","Non. Les scores de chaque trou doivent être vérifiés."],["Laisser le marqueur décider seul de tout doute","Non. Le Comité doit être consulté si nécessaire."]]},{"v":2,"p":"Une incertitude subsiste sur un score de trou avant remise. Que faire ?","i":"Joueuse et marqueur vérifiant ensemble une carte de score. Une incertitude subsiste sur un score de trou avant remise. Que faire ?","x":"Le marqueur certifie les scores des trous; le joueur doit vérifier ses scores, résoudre les doutes avec le Comité et certifier puis rendre la carte selon les modalités prévues. Le Comité additionne le total et applique les handicaps.","o":[["Consulter le Comité et résoudre le doute avant remise","Oui. Il faut rendre des scores vérifiés."],["Rendre la carte sans en parler","Non. Le doute doit être traité."],["Modifier le score au hasard","Non. Il faut établir le score exact."]]}]},
  {"n":62,"r":"Règle 3.3b(3)","s":"Mia rend en stroke play une carte avec 6 sur un trou où elle avait fait 5.","e":"Si le score rendu pour un trou est plus élevé que le score réel, le score plus élevé est retenu. Il est donc essentiel de vérifier chaque trou avant de rendre la carte.","a":"Je corrige toute erreur connue avant de rendre la carte.","m":"Penser qu’un score trop élevé sera automatiquement réduit après remise.","c":"Comparez une carte avant et après remise avec un trou inscrit trop haut.","v":"Carte de score indiquant six coups là où cinq ont été joués.","q":[{"v":0,"p":"Une carte rendue indique un score de trou trop élevé. Quel score compte ?","i":"Carte de score indiquant six coups là où cinq ont été joués. Une carte rendue indique un score de trou trop élevé. Quel score compte ?","x":"Si le score rendu pour un trou est plus élevé que le score réel, le score plus élevé est retenu. Il est donc essentiel de vérifier chaque trou avant de rendre la carte.","o":[["Le score rendu, plus élevé","Oui. La Règle 3.3b(3) retient ce score."],["Toujours le score réel plus bas","Non. L’erreur trop élevée reste sur la carte rendue."],["Une disqualification automatique","Non. Un score trop élevé n’a pas cet effet."]]},{"v":1,"p":"Le score réel de Tom est 5 mais sa carte rendue indique 6. Que retient-on ?","i":"Carte de score indiquant six coups là où cinq ont été joués. Le score réel de Tom est 5 mais sa carte rendue indique 6. Que retient-on ?","x":"Si le score rendu pour un trou est plus élevé que le score réel, le score plus élevé est retenu. Il est donc essentiel de vérifier chaque trou avant de rendre la carte.","o":[["Le score rendu, plus élevé","Oui. La Règle 3.3b(3) retient ce score."],["Toujours le score réel plus bas","Non. L’erreur trop élevée reste sur la carte rendue."],["Une disqualification automatique","Non. Un score trop élevé n’a pas cet effet."]]},{"v":2,"p":"Après remise, Léa remarque qu’un trou est inscrit trop haut. Est-il automatiquement réduit ?","i":"Carte de score indiquant six coups là où cinq ont été joués. Après remise, Léa remarque qu’un trou est inscrit trop haut. Est-il automatiquement réduit ?","x":"Si le score rendu pour un trou est plus élevé que le score réel, le score plus élevé est retenu. Il est donc essentiel de vérifier chaque trou avant de rendre la carte.","o":[["Non, le score trop élevé rendu est retenu","Oui. Il faut corriger avant remise."],["Oui, il est réduit automatiquement","Non. La règle retient le score rendu."],["Oui, le marqueur choisit après coup","Non. La carte rendue fixe ce score."]]}]},
  {"n":63,"r":"Règle 3.3b(3)","s":"En stroke play, Léo rend une carte indiquant 4 sur un trou où il a fait 5, pénalités connues comprises.","e":"Un score de trou rendu plus bas que le score réel entraîne normalement la disqualification. Une exception existe si une pénalité inconnue du joueur avant la remise explique l’écart; le Comité ajoute alors la pénalité pertinente.","a":"Je vérifie tous mes coups et pénalités connus avant de rendre la carte et consulte le Comité en cas de doute.","m":"Croire qu’une erreur trop basse se corrige librement après remise.","c":"Comparez score trop haut, trop bas et pénalité réellement inconnue.","v":"Carte de score indiquant quatre coups alors que cinq ont été joués.","q":[{"v":0,"p":"Quel risque normal présente un score de trou rendu trop bas ?","i":"Carte de score indiquant quatre coups alors que cinq ont été joués. Quel risque normal présente un score de trou rendu trop bas ?","x":"Un score de trou rendu plus bas que le score réel entraîne normalement la disqualification. Une exception existe si une pénalité inconnue du joueur avant la remise explique l’écart; le Comité ajoute alors la pénalité pertinente.","o":[["Disqualification normale, sous réserve de l’exception","Oui. Une pénalité inconnue peut changer l’analyse."],["Le score trop bas est toujours accepté","Non. Il ne reflète pas le trou joué."],["Le joueur reçoit toujours seulement un coup","Non. La règle prévoit généralement la disqualification."]]},{"v":1,"p":"La carte de Mia indique 4 au lieu de 5 coups connus. Quelle conséquence normale ?","i":"Carte de score indiquant quatre coups alors que cinq ont été joués. La carte de Mia indique 4 au lieu de 5 coups connus. Quelle conséquence normale ?","x":"Un score de trou rendu plus bas que le score réel entraîne normalement la disqualification. Une exception existe si une pénalité inconnue du joueur avant la remise explique l’écart; le Comité ajoute alors la pénalité pertinente.","o":[["Disqualification normale, sous réserve de l’exception","Oui. Une pénalité inconnue peut changer l’analyse."],["Le score trop bas est toujours accepté","Non. Il ne reflète pas le trou joué."],["Le joueur reçoit toujours seulement un coup","Non. La règle prévoit généralement la disqualification."]]},{"v":2,"p":"Une pénalité était inconnue du joueur avant la remise. Faut-il examiner une exception avant de conclure ?","i":"Carte de score indiquant quatre coups alors que cinq ont été joués. Une pénalité était inconnue du joueur avant la remise. Faut-il examiner une exception avant de conclure ?","x":"Un score de trou rendu plus bas que le score réel entraîne normalement la disqualification. Une exception existe si une pénalité inconnue du joueur avant la remise explique l’écart; le Comité ajoute alors la pénalité pertinente.","o":[["Oui, une pénalité inconnue peut constituer une exception","Oui. Le Comité doit examiner les circonstances."],["Non, aucune exception n’existe","Non. La Règle 3.3b(3) en prévoit une."],["Oui, toute pénalité oubliée est ignorée","Non. L’exception ne supprime pas la pénalité."]]}]},
  {"n":64,"r":"Règle 3.3c","s":"En stroke play classique, Nora ramasse sa balle à trente centimètres du trou parce que son partenaire lui « donne » le putt.","e":"Chaque trou doit être terminé en entrant la balle dans le trou en stroke play, sauf formes de jeu spécifiques. Si la balle est ramassée, le joueur doit corriger avant de commencer le trou suivant, ou avant de rendre sa carte au dernier trou.","a":"Je termine chaque trou en mettant la balle dans le trou, même si le coup paraît facile.","m":"Importer une concession de match play dans un stroke play classique.","c":"Faites distinguer match play, stroke play classique et formes particulières.","v":"Balle très près du trou qu’une joueuse doit encore putter.","q":[{"v":0,"p":"Peut-on accepter un putt « donné » en stroke play classique ?","i":"Balle très près du trou qu’une joueuse doit encore putter. Peut-on accepter un putt « donné » en stroke play classique ?","x":"Chaque trou doit être terminé en entrant la balle dans le trou en stroke play, sauf formes de jeu spécifiques. Si la balle est ramassée, le joueur doit corriger avant de commencer le trou suivant, ou avant de rendre sa carte au dernier trou.","o":[["Non, il faut terminer le trou","Oui. La balle doit entrer dans le trou."],["Oui, si la distance est courte","Non. La distance ne crée pas de concession."],["Oui, si le partenaire le dit","Non. La concession appartient au match play."]]},{"v":1,"p":"À dix centimètres du trou, Max ramasse sa balle sans entrer. Que doit-il faire à temps ?","i":"Balle très près du trou qu’une joueuse doit encore putter. À dix centimètres du trou, Max ramasse sa balle sans entrer. Que doit-il faire à temps ?","x":"Chaque trou doit être terminé en entrant la balle dans le trou en stroke play, sauf formes de jeu spécifiques. Si la balle est ramassée, le joueur doit corriger avant de commencer le trou suivant, ou avant de rendre sa carte au dernier trou.","o":[["Terminer le trou avant le départ suivant","Oui. La faute doit être corrigée à temps."],["Continuer au trou suivant sans correction","Non. Le trou n’a pas été terminé."],["Accepter la concession du partenaire","Non. Elle n’existe pas en stroke play classique."]]},{"v":2,"p":"Un partenaire dit à Emma que son dernier coup est accordé en stroke play. Est-ce suffisant ?","i":"Balle très près du trou qu’une joueuse doit encore putter. Un partenaire dit à Emma que son dernier coup est accordé en stroke play. Est-ce suffisant ?","x":"Chaque trou doit être terminé en entrant la balle dans le trou en stroke play, sauf formes de jeu spécifiques. Si la balle est ramassée, le joueur doit corriger avant de commencer le trou suivant, ou avant de rendre sa carte au dernier trou.","o":[["Non, elle doit terminer le trou","Oui. La concession ne s’applique pas à ce stroke play."],["Oui, le partenaire peut concéder","Non. Il ne peut pas modifier la forme de jeu."],["Oui, si le putt est court","Non. La distance est sans effet."]]}]},
  {"n":65,"r":"Règle 3.2b","s":"En match play, Zoé dit clairement à son adversaire que son prochain putt est concédé.","e":"Un joueur peut concéder le prochain coup, un trou ou le match à son adversaire en match play. Une concession clairement communiquée est définitive et ne peut être retirée.","a":"J’annonce sans ambiguïté ce que je concède, et je considère la concession comme définitive.","m":"Faire comme si une concession pouvait être annulée après le résultat du coup suivant.","c":"Faites jouer des phrases ambiguës puis des concessions claires.","v":"Deux adversaires sur le green, l’un concédant calmement un court putt.","q":[{"v":0,"p":"Dans quelle forme de jeu peut-on concéder le prochain coup de l’adversaire ?","i":"Deux adversaires sur le green, l’un concédant calmement un court putt. Dans quelle forme de jeu peut-on concéder le prochain coup de l’adversaire ?","x":"Un joueur peut concéder le prochain coup, un trou ou le match à son adversaire en match play. Une concession clairement communiquée est définitive et ne peut être retirée.","o":[["En match play, avec une concession définitive","Oui. La concession claire ne se retire pas."],["En tout stroke play individuel","Non. Chaque trou doit normalement être achevé."],["Seulement après que le coup a été joué","Non. La concession intervient avant le coup concerné."]]},{"v":1,"p":"En match play, Léa concède clairement un putt. Peut-elle retirer sa concession ?","i":"Deux adversaires sur le green, l’un concédant calmement un court putt. En match play, Léa concède clairement un putt. Peut-elle retirer sa concession ?","x":"Un joueur peut concéder le prochain coup, un trou ou le match à son adversaire en match play. Une concession clairement communiquée est définitive et ne peut être retirée.","o":[["Non, une concession claire est définitive","Oui. Elle ne peut pas être retirée."],["Oui, avant le coup suivant","Non. Le retrait n’est pas permis."],["Oui, si l’adversaire refuse","Non. Une concession valable est définitive."]]},{"v":2,"p":"Mia concède le trou entier à son adversaire en match play. Est-ce une possibilité ?","i":"Deux adversaires sur le green, l’un concédant calmement un court putt. Mia concède le trou entier à son adversaire en match play. Est-ce une possibilité ?","x":"Un joueur peut concéder le prochain coup, un trou ou le match à son adversaire en match play. Une concession clairement communiquée est définitive et ne peut être retirée.","o":[["Oui, un trou peut être concédé en match play","Oui. La Règle 3.2b le permet."],["Non, seul un putt peut être concédé","Non. Le trou et le match peuvent aussi l’être."],["Oui, mais elle peut ensuite changer d’avis","Non. La concession est définitive."]]}]},
  {"n":66,"r":"Règle 5.3a","s":"Le départ officiel de Yanis est fixé à 9 h 00 et il arrive prêt à 9 h 03.","e":"L’heure fixée par le Comité est exacte; le joueur doit être prêt au point de départ à cette heure. Un retard de cinq minutes ou moins entraîne normalement la pénalité générale au premier trou; au-delà, disqualification, sauf circonstance exceptionnelle reconnue.","a":"Je me présente prêt à jouer avant l’heure précise et signale immédiatement tout retard au Comité.","m":"Croire qu’une heure affichée donne automatiquement une minute de tolérance sans pénalité.","c":"Simulez arrivée à l’heure, trois minutes tard et six minutes tard.","v":"Horloge du départ et jeune joueur arrivant avec son sac.","q":[{"v":0,"p":"Un joueur arrive prêt trois minutes après son heure précise. Quelle conséquence normale ?","i":"Horloge du départ et jeune joueur arrivant avec son sac. Un joueur arrive prêt trois minutes après son heure précise. Quelle conséquence normale ?","x":"L’heure fixée par le Comité est exacte; le joueur doit être prêt au point de départ à cette heure. Un retard de cinq minutes ou moins entraîne normalement la pénalité générale au premier trou; au-delà, disqualification, sauf circonstance exceptionnelle reconnue.","o":[["La pénalité générale pour un retard de cinq minutes ou moins","Oui. Au-delà de cinq minutes, la conséquence normale est plus grave."],["Aucune pénalité dans les cinq premières minutes","Non. Cette fenêtre atténue la sanction mais n’efface pas la faute."],["Toujours la disqualification à une seconde de retard","Non. La règle prévoit l’exception de cinq minutes."]]},{"v":1,"p":"Le départ de Léa est 9 h 00; elle est prête à 9 h 03. Quelle règle de retard s’applique normalement ?","i":"Horloge du départ et jeune joueur arrivant avec son sac. Le départ de Léa est 9 h 00; elle est prête à 9 h 03. Quelle règle de retard s’applique normalement ?","x":"L’heure fixée par le Comité est exacte; le joueur doit être prêt au point de départ à cette heure. Un retard de cinq minutes ou moins entraîne normalement la pénalité générale au premier trou; au-delà, disqualification, sauf circonstance exceptionnelle reconnue.","o":[["La pénalité générale pour un retard de cinq minutes ou moins","Oui. Au-delà de cinq minutes, la conséquence normale est plus grave."],["Aucune pénalité dans les cinq premières minutes","Non. Cette fenêtre atténue la sanction mais n’efface pas la faute."],["Toujours la disqualification à une seconde de retard","Non. La règle prévoit l’exception de cinq minutes."]]},{"v":2,"p":"Max arrive six minutes en retard sans circonstance exceptionnelle. Est-ce la même pénalité qu’à trois minutes ?","i":"Horloge du départ et jeune joueur arrivant avec son sac. Max arrive six minutes en retard sans circonstance exceptionnelle. Est-ce la même pénalité qu’à trois minutes ?","x":"L’heure fixée par le Comité est exacte; le joueur doit être prêt au point de départ à cette heure. Un retard de cinq minutes ou moins entraîne normalement la pénalité générale au premier trou; au-delà, disqualification, sauf circonstance exceptionnelle reconnue.","o":[["Non, la disqualification est normalement applicable","Oui. Six minutes dépassent la fenêtre de cinq minutes."],["Oui, seulement la pénalité générale","Non. Cette exception s’arrête à cinq minutes."],["Aucune pénalité si le groupe n’est pas parti","Non. L’heure fixée est exacte, sauf circonstances prévues."]]}]}
  ,
  {"n":67,"r":"Règle 5.6b ; Règle 1.2a","s":"Entre ses coups, Chloé tarde à préparer son club et son groupe prend du retard.","e":"Chaque joueur contribue à une cadence rapide et raisonnable, prépare le coup à l’avance et avance sans délai inutile. Une politique de cadence du Comité peut préciser les temps et pénalités; une recommandation usuelle est de jouer en 40 secondes au plus quand le tour vient.","a":"Je prépare ma décision en marchant et suis prêt quand vient mon tour, sans sacrifier la sécurité.","m":"Croire que la cadence ne concerne que le temps du swing.","c":"Chronométrez la préparation, le déplacement et la transition vers le départ suivant.","v":"Groupe junior avançant ensemble sur le fairway vers leurs balles.","q":[{"v":0,"p":"Quelle action aide à maintenir une cadence raisonnable ?","i":"Groupe junior avançant ensemble sur le fairway vers leurs balles. Quelle action aide à maintenir une cadence raisonnable ?","x":"Chaque joueur contribue à une cadence rapide et raisonnable, prépare le coup à l’avance et avance sans délai inutile. Une politique de cadence du Comité peut préciser les temps et pénalités; une recommandation usuelle est de jouer en 40 secondes au plus quand le tour vient.","o":[["Préparer son coup à l’avance et avancer sans délai","Oui. La cadence couvre aussi les déplacements."],["Se précipiter au mépris de la sécurité","Non. La sécurité reste prioritaire."],["Attendre le green pour choisir tous ses clubs","Non. Cela crée un retard évitable."]]},{"v":1,"p":"En marchant vers sa balle, Léa peut préparer son choix de club. Est-ce utile ?","i":"Groupe junior avançant ensemble sur le fairway vers leurs balles. En marchant vers sa balle, Léa peut préparer son choix de club. Est-ce utile ?","x":"Chaque joueur contribue à une cadence rapide et raisonnable, prépare le coup à l’avance et avance sans délai inutile. Une politique de cadence du Comité peut préciser les temps et pénalités; une recommandation usuelle est de jouer en 40 secondes au plus quand le tour vient.","o":[["Oui, préparer son coup à l’avance aide la cadence","Oui. Cela réduit l’attente quand vient son tour."],["Non, il faut attendre immobile","Non. La préparation raisonnable est encouragée."],["Oui, même en ignorant la sécurité","Non. La sécurité reste indispensable."]]},{"v":2,"p":"Le joueur attend son tour pour commencer toute préparation et ralentit le groupe. Quelle habitude changer ?","i":"Groupe junior avançant ensemble sur le fairway vers leurs balles. Le joueur attend son tour pour commencer toute préparation et ralentit le groupe. Quelle habitude changer ?","x":"Chaque joueur contribue à une cadence rapide et raisonnable, prépare le coup à l’avance et avance sans délai inutile. Une politique de cadence du Comité peut préciser les temps et pénalités; une recommandation usuelle est de jouer en 40 secondes au plus quand le tour vient.","o":[["Préparer son coup à l’avance et avancer sans délai","Oui. La cadence couvre aussi les déplacements."],["Se précipiter au mépris de la sécurité","Non. La sécurité reste prioritaire."],["Attendre le green pour choisir tous ses clubs","Non. Cela crée un retard évitable."]]}]},
  {"n":68,"r":"Règle 1.2a","s":"Avant de frapper, Noé voit des promeneurs proches de sa ligne de jeu.","e":"L’esprit du jeu exige de veiller à la sécurité d’autrui. Le joueur attend que la voie soit dégagée et crie immédiatement un avertissement si sa balle risque de toucher quelqu’un.","a":"Je regarde devant et autour, attends une zone sûre et alerte immédiatement en cas de danger.","m":"Jouer vite en comptant sur les autres pour se protéger.","c":"Mettez en scène des personnes hors de portée puis sur la trajectoire, sans frapper de balle.","v":"Jeune golfeur s’arrêtant avant son coup car des personnes traversent au loin.","q":[{"v":0,"p":"Que faire si des personnes sont à portée de ton coup ?","i":"Jeune golfeur s’arrêtant avant son coup car des personnes traversent au loin. Que faire si des personnes sont à portée de ton coup ?","x":"L’esprit du jeu exige de veiller à la sécurité d’autrui. Le joueur attend que la voie soit dégagée et crie immédiatement un avertissement si sa balle risque de toucher quelqu’un.","o":[["Attendre la sécurité et avertir immédiatement si danger","Oui. La considération pour autrui prime."],["Jouer en supposant qu’ils regardent","Non. Le joueur doit prévenir le risque."],["Ne jamais avertir après un coup","Non. Un avertissement immédiat peut protéger autrui."]]},{"v":1,"p":"Un groupe traverse devant Mia alors qu’elle est prête à jouer. Quelle décision ?","i":"Jeune golfeur s’arrêtant avant son coup car des personnes traversent au loin. Un groupe traverse devant Mia alors qu’elle est prête à jouer. Quelle décision ?","x":"L’esprit du jeu exige de veiller à la sécurité d’autrui. Le joueur attend que la voie soit dégagée et crie immédiatement un avertissement si sa balle risque de toucher quelqu’un.","o":[["Attendre la sécurité et avertir immédiatement si danger","Oui. La considération pour autrui prime."],["Jouer en supposant qu’ils regardent","Non. Le joueur doit prévenir le risque."],["Ne jamais avertir après un coup","Non. Un avertissement immédiat peut protéger autrui."]]},{"v":2,"p":"La balle de Zoé part vers quelqu’un. Quelle réaction immédiate ?","i":"Jeune golfeur s’arrêtant avant son coup car des personnes traversent au loin. La balle de Zoé part vers quelqu’un. Quelle réaction immédiate ?","x":"L’esprit du jeu exige de veiller à la sécurité d’autrui. Le joueur attend que la voie soit dégagée et crie immédiatement un avertissement si sa balle risque de toucher quelqu’un.","o":[["Crier immédiatement un avertissement","Oui. Il faut alerter les personnes en danger."],["Attendre de voir où la balle finit","Non. L’avertissement doit être immédiat."],["Ne rien dire pour ne pas distraire","Non. La sécurité prime."]]}]},
  {"n":69,"r":"Règle 1.2a","s":"Après un coup, une motte de gazon se détache et le bunker voisin garde des traces de pas.","e":"Prendre soin du parcours fait partie de l’esprit du jeu : replacer les divots lorsque c’est approprié, lisser le bunker et réparer les marques de balle. Les règles locales ou consignes du club peuvent guider les gestes.","a":"Je remets le terrain en état sans retarder inutilement le groupe.","m":"Laisser les traces de jeu aux suivants ou réparer de manière qui améliore illicitement mon coup.","c":"Faites trois ateliers rapides : divot, râteau et relève-pitch.","v":"Junior replaçant une motte de gazon et un autre lissant un bunker.","q":[{"v":0,"p":"Quel geste illustre le soin du parcours après un coup ?","i":"Junior replaçant une motte de gazon et un autre lissant un bunker. Quel geste illustre le soin du parcours après un coup ?","x":"Prendre soin du parcours fait partie de l’esprit du jeu : replacer les divots lorsque c’est approprié, lisser le bunker et réparer les marques de balle. Les règles locales ou consignes du club peuvent guider les gestes.","o":[["Réparer les dommages et lisser le bunker","Oui. Le respect du terrain fait partie du jeu."],["Laisser le terrain tel quel pour les suivants","Non. Les joueurs doivent en prendre soin."],["Endommager davantage pour égaliser","Non. Le soin du parcours ne consiste pas à créer des dégâts."]]},{"v":1,"p":"Après être sorti du bunker, Max laisse de profondes traces de pas. Que devrait-il faire ?","i":"Junior replaçant une motte de gazon et un autre lissant un bunker. Après être sorti du bunker, Max laisse de profondes traces de pas. Que devrait-il faire ?","x":"Prendre soin du parcours fait partie de l’esprit du jeu : replacer les divots lorsque c’est approprié, lisser le bunker et réparer les marques de balle. Les règles locales ou consignes du club peuvent guider les gestes.","o":[["Lisser ses traces avec le râteau","Oui. Il laisse le bunker en bon état."],["Les laisser pour le groupe suivant","Non. Cela gêne les autres."],["Creuser une nouvelle zone plate","Non. Il ne faut pas endommager davantage."]]},{"v":2,"p":"Léa repère une marque d’impact sur le green. Quel comportement attendu ?","i":"Junior replaçant une motte de gazon et un autre lissant un bunker. Léa repère une marque d’impact sur le green. Quel comportement attendu ?","x":"Prendre soin du parcours fait partie de l’esprit du jeu : replacer les divots lorsque c’est approprié, lisser le bunker et réparer les marques de balle. Les règles locales ou consignes du club peuvent guider les gestes.","o":[["Réparer raisonnablement la marque","Oui. Cela protège le green."],["La laisser pour le personnel","Non. Le joueur peut et devrait la réparer."],["Aplatir tout le green autour","Non. La réparation doit rester raisonnable."]]}]},
  {"n":70,"r":"Règle 22.3","s":"En foursome, Ana a joué le départ du trou 1 et son partenaire Léo doit effectuer le coup suivant.","e":"Les deux partenaires jouent une seule balle en alternant les coups sur chaque trou et alternent également le joueur qui prend le départ des trous successifs. Les coups de pénalité n’inversent pas l’ordre; si un coup doit être rejoué, c’est normalement le même partenaire.","a":"Je repère qui doit jouer le prochain coup et qui prendra le prochain départ.","m":"Croire qu’une pénalité fait passer le tour au partenaire.","c":"Utilisez une balle et des cartes portant les deux prénoms pour suivre six coups et deux départs.","v":"Deux partenaires alternant leurs coups avec une seule balle.","q":[{"v":0,"p":"En foursome, combien de balles la paire joue-t-elle normalement par trou ?","i":"Deux partenaires alternant leurs coups avec une seule balle. En foursome, combien de balles la paire joue-t-elle normalement par trou ?","x":"Les deux partenaires jouent une seule balle en alternant les coups sur chaque trou et alternent également le joueur qui prend le départ des trous successifs. Les coups de pénalité n’inversent pas l’ordre; si un coup doit être rejoué, c’est normalement le même partenaire.","o":[["Une seule balle, avec alternance des partenaires","Oui. Le rythme alterne les coups, pas les pénalités."],["Chacun joue sa propre balle","Non. Ce serait du quatre balles."],["Le même joueur peut choisir tous les coups","Non. L’alternance est obligatoire."]]},{"v":1,"p":"Ana joue le départ, puis Léo le deuxième coup. Quelle alternance suit le coup suivant ?","i":"Deux partenaires alternant leurs coups avec une seule balle. Ana joue le départ, puis Léo le deuxième coup. Quelle alternance suit le coup suivant ?","x":"Les deux partenaires jouent une seule balle en alternant les coups sur chaque trou et alternent également le joueur qui prend le départ des trous successifs. Les coups de pénalité n’inversent pas l’ordre; si un coup doit être rejoué, c’est normalement le même partenaire.","o":[["Ana joue normalement le troisième coup","Oui. Les partenaires alternent les coups sur le trou."],["Léo joue à nouveau","Non. Il vient de jouer le deuxième."],["Ils choisissent librement","Non. L’ordre est fixé."]]},{"v":2,"p":"Un coup de pénalité est ajouté à la paire. Change-t-il le joueur du prochain coup ?","i":"Deux partenaires alternant leurs coups avec une seule balle. Un coup de pénalité est ajouté à la paire. Change-t-il le joueur du prochain coup ?","x":"Les deux partenaires jouent une seule balle en alternant les coups sur chaque trou et alternent également le joueur qui prend le départ des trous successifs. Les coups de pénalité n’inversent pas l’ordre; si un coup doit être rejoué, c’est normalement le même partenaire.","o":[["Non, les coups de pénalité n’inversent pas l’ordre","Oui. L’alternance suit les coups joués."],["Oui, chaque pénalité change de partenaire","Non. Les pénalités ne sont pas des coups alternés."],["Oui, si le score du trou augmente","Non. Le score n’est pas le critère."]]}]},
  {"n":71,"r":"Règle 23.1-23.2","s":"En quatre balles, Inès et Sami jouent chacun leur balle et terminent le trou en quatre et six coups.","e":"Les partenaires jouent chacun leur balle; le score de la paire sur le trou est le plus bas des deux scores valides. Si un seul partenaire termine valablement, son score peut compter pour la paire.","a":"Je joue ma balle et note quel partenaire a réalisé le score retenu.","m":"Additionner les deux scores ou croire que chacun doit absolument terminer le trou.","c":"Utilisez deux cartes fictives et trouvez le score de la paire sur plusieurs trous.","v":"Deux partenaires jouant chacun une balle et comparant leurs cartes.","q":[{"v":0,"p":"Les partenaires marquent quatre et six coups. Quel score compte pour la paire ?","i":"Deux partenaires jouant chacun une balle et comparant leurs cartes. Les partenaires marquent quatre et six coups. Quel score compte pour la paire ?","x":"Les partenaires jouent chacun leur balle; le score de la paire sur le trou est le plus bas des deux scores valides. Si un seul partenaire termine valablement, son score peut compter pour la paire.","o":[["Le score valable le plus bas d’un partenaire","Oui. La paire retient le plus bas score valide."],["La somme des deux scores","Non. Il ne s’agit pas d’un total des partenaires."],["Toujours le score du premier à jouer","Non. L’ordre de jeu ne décide pas du score."]]},{"v":1,"p":"En quatre balles, un seul partenaire termine le trou valablement en cinq. Un score de paire est-il possible ?","i":"Deux partenaires jouant chacun une balle et comparant leurs cartes. En quatre balles, un seul partenaire termine le trou valablement en cinq. Un score de paire est-il possible ?","x":"Les partenaires jouent chacun leur balle; le score de la paire sur le trou est le plus bas des deux scores valides. Si un seul partenaire termine valablement, son score peut compter pour la paire.","o":[["Oui, le score de ce partenaire peut compter","Oui. L’autre n’est pas obligé de terminer."],["Non, les deux doivent toujours entrer","Non. Le score valable d’un seul peut suffire."],["Oui, en additionnant un score fictif","Non. Seul un score réellement valable compte."]]},{"v":2,"p":"Deux partenaires jouent chacun une balle. Additionne-t-on leurs scores sur le trou ?","i":"Deux partenaires jouant chacun une balle et comparant leurs cartes. Deux partenaires jouent chacun une balle. Additionne-t-on leurs scores sur le trou ?","x":"Les partenaires jouent chacun leur balle; le score de la paire sur le trou est le plus bas des deux scores valides. Si un seul partenaire termine valablement, son score peut compter pour la paire.","o":[["Non, on retient le plus bas score valable","Oui. Les scores ne sont pas additionnés."],["Oui, on additionne les deux","Non. Ce n’est pas le calcul du quatre balles."],["On retient toujours le plus haut","Non. Le plus bas score valable compte."]]}]},
  {"n":72,"r":"Règle 1.3a ; Procédures du Comité, règles locales","s":"Avant le tournoi, un panneau du club annonce qu’une zone précise du parcours est terrain en réparation.","e":"Les règles locales dûment adoptées et publiées par le Comité font partie des règles du tour et doivent être lues et appliquées. Elles ne peuvent pas modifier librement les Règles de golf; leur texte exact, leur périmètre et leur date d’application comptent.","a":"Je lis les règles locales du jour, repère les zones concernées et demande au Comité si le texte est ambigu.","m":"Appliquer une ancienne règle locale ou inventer une option non annoncée.","c":"Donnez deux feuilles de règles locales de dates différentes et faites identifier celle du tour.","v":"Panneau de règles locales du club près du premier départ, junior le consultant.","q":[{"v":0,"p":"Que faire avec une règle locale publiée pour la compétition du jour ?","i":"Panneau de règles locales du club près du premier départ, junior le consultant. Que faire avec une règle locale publiée pour la compétition du jour ?","x":"Les règles locales dûment adoptées et publiées par le Comité font partie des règles du tour et doivent être lues et appliquées. Elles ne peuvent pas modifier librement les Règles de golf; leur texte exact, leur périmètre et leur date d’application comptent.","o":[["Lire et appliquer la règle locale en vigueur","Oui. Le texte du Comité applicable au tour compte."],["Suivre une ancienne consigne mémorisée","Non. Elle peut avoir changé."],["Inventer une option plus favorable","Non. Seules les règles adoptées s’appliquent."]]},{"v":1,"p":"Un panneau actuel définit une zone de réparation. Quelle source consulter avant de jouer ?","i":"Panneau de règles locales du club près du premier départ, junior le consultant. Un panneau actuel définit une zone de réparation. Quelle source consulter avant de jouer ?","x":"Les règles locales dûment adoptées et publiées par le Comité font partie des règles du tour et doivent être lues et appliquées. Elles ne peuvent pas modifier librement les Règles de golf; leur texte exact, leur périmètre et leur date d’application comptent.","o":[["Lire et appliquer la règle locale en vigueur","Oui. Le texte du Comité applicable au tour compte."],["Suivre une ancienne consigne mémorisée","Non. Elle peut avoir changé."],["Inventer une option plus favorable","Non. Seules les règles adoptées s’appliquent."]]},{"v":2,"p":"Mia se souvient d’une ancienne règle locale mais le panneau actuel dit autre chose. Que doit-elle suivre ?","i":"Panneau de règles locales du club près du premier départ, junior le consultant. Mia se souvient d’une ancienne règle locale mais le panneau actuel dit autre chose. Que doit-elle suivre ?","x":"Les règles locales dûment adoptées et publiées par le Comité font partie des règles du tour et doivent être lues et appliquées. Elles ne peuvent pas modifier librement les Règles de golf; leur texte exact, leur périmètre et leur date d’application comptent.","o":[["La règle locale actuelle en vigueur","Oui. Une ancienne consigne peut avoir changé."],["Son souvenir de l’ancienne règle","Non. Il faut vérifier le texte applicable."],["L’option la plus favorable inventée","Non. Le joueur applique les règles publiées."]]}]}
]
$cards$::jsonb) loop
    v_card_no := (v_card->>'n')::integer;
    if v_card_no not between 13 and 72 or v_card_no=any(v_seen)
      or not (v_card ?& array['s','e','a','m','c','r','v','q'])
      or jsonb_typeof(v_card->'q')<>'array'
      or jsonb_array_length(v_card->'q')<>3
      or (
        select array_agg((question_row.value->>'v')::integer order by (question_row.value->>'v')::integer)
        from jsonb_array_elements(v_card->'q') question_row
      ) is distinct from array[0,1,2]
      or exists (
        select 1 from jsonb_each_text(v_card) field
        where field.key in ('s','e','a','m','c','r','v') and trim(field.value)=''
      ) then
      raise exception 'Incomplete or duplicate editorial card %',v_card_no;
    end if;
    v_seen := array_append(v_seen,v_card_no);
    v_key := 'junior-rule-' || lpad(v_card_no::text,2,'0');
    for v_question in select value from jsonb_array_elements(v_card->'q') loop
      if (v_question->>'v')::integer not between 0 and 2
        or jsonb_array_length(v_question->'o') not between 3 and 4
        or trim(coalesce(v_question->>'p',''))=''
        or trim(coalesce(v_question->>'x',''))=''
        or trim(coalesce(v_question->>'i',''))=''
        or exists (
          select 1 from jsonb_array_elements(v_question->'o') option_row
          where jsonb_typeof(option_row.value)<>'array'
            or jsonb_array_length(option_row.value)<>2
            or trim(coalesce(option_row.value->>0,''))=''
            or trim(coalesce(option_row.value->>1,''))=''
        ) then
        raise exception 'Incomplete editorial question for %',v_key;
      end if;
    end loop;
    v_count := v_count+1;
    v_question_count := v_question_count+3;
    select cv.id into v_version_id
    from public.rules_card_versions cv
    join public.rules_cards c on c.id=cv.card_id
    join public.rules_series_cards sc on sc.card_version_id=cv.id
    join public.rules_series series on series.id=sc.series_id
    join public.rules_seasons season on season.id=series.season_id
    where c.stable_key=v_key and cv.version=1 and cv.locale='fr'
      and season.slug='junior-rules-2027'
      and series.position=((v_card_no-1)/6)+1;
    if v_version_id is null then raise exception 'Missing seed card %',v_key; end if;
    if exists(select 1 from public.rules_card_versions where id=v_version_id and approved_at is not null)
      or exists (
        select 1 from public.rules_series_cards sc
        join public.rules_series series on series.id=sc.series_id
        where sc.card_version_id=v_version_id and series.status in ('published','locked','archived')
      ) then
      continue; -- A completed version is immutable, even on a later re-run.
    end if;

    update public.rules_card_versions set
      situation=v_card->>'s',simple_explanation=v_card->>'e',action_text=v_card->>'a',
      common_mistake=v_card->>'m',coach_tip=v_card->>'c',official_reference=v_card->>'r',
      reference_version='R&A Rules of Golf 2023 + Additional Clarifications 2026-07-01',
      illustration_prompt='Illustration ActiviTee originale, sans texte ni logo tiers : '||(v_card->>'v'),
      image_alt=v_card->>'v',image_status='pending',human_review_required=true
    where id=v_version_id and situation like 'Une situation de jeu junior doit illustrer clairement :%';

    for v_question in select value from jsonb_array_elements(v_card->'q') loop
      v_variant := (v_question->>'v')::integer;
      v_kind := case when v_variant=0 then 'practice' else 'official' end;
      insert into public.rules_questions(card_version_id,kind,variant,prompt,explanation,illustration_prompt,image_alt,allows_multiple,editorial_status)
      values(v_version_id,v_kind,greatest(v_variant,1),v_question->>'p',v_question->>'x',
        'Illustration ActiviTee originale, sans texte : '||(v_question->>'i'),v_question->>'i',false,'needs_review')
      on conflict(card_version_id,kind,variant) do nothing
      returning id into v_question_id;
      if v_question_id is not null then
        v_position := 0;
        for v_answer in select value from jsonb_array_elements(v_question->'o') loop
          v_position := v_position+1;
          insert into public.rules_question_options(question_id,position,label,is_correct,explanation)
          values(v_question_id,v_position,v_answer->>0,v_position=1,v_answer->>1);
        end loop;
      end if;
    end loop;
  end loop;
  if v_count<>60 or v_question_count<>180 then
    raise exception 'Curriculum incomplete: % cards, % questions (expected 60/180)',v_count,v_question_count;
  end if;
end;
$migration$;
